COLLDATA("tadabburar","ar",[[254,"§الرعد\nwords\nأُكُلُهَاثَمَرُهَا.\nعُقبَىعَاقِبَةُ.\nالأَحزَابِالمُتَحَزِّبِينَ المُتَجَمِّعِينَ عَلَى الكُفرِ.\nنَنقُصُهَا مِن أَطرَافِهَابِفَتحِ المُسلِمِينَ بِلادَ المُشرِكِينَ.\nلا مُعَقِّبَلا رَادَّ، وَلا مُبطِلَ.\ndeeds\nتذكر ما فتح الله به عليك من حفظ آيات من كتاب الله تعالى أو تدبرها، و افرح بذلك واحمد الله؛ فأنت على خير.\nاسأل الله أن يثبتك على دينه، واستعذ به من اتباع أهواء الذين لا يوقنون.\nاسأل الله أن يكثر من العلماء وطلبة العلم في الأمة، وأن يزيد في أعمارهم.\nguid\nنهتم بمعرفة اللغة العربية ونشرها؛ لأنها أساس فهم القرآن.\nاحذر من سماع شبهات الكفار وتلقفها؛ فإن عاقبة ذلك أن يكلك الله تعالى إلى نفسك؛ لأنك توليت عن شرعه.\nاجتهد في تبليغ الدعوة للناس، وأمَّا هدايتهم فبيد الله تعالى.\nrefl\nمَّثَلُ ٱلۡجَنَّةِ ٱلَّتِي وُعِدَ ٱلۡمُتَّقُونَۖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۖ أُكُلُهَا دَآئِمٞ وَظِلُّهَاۚ\n﴿أُكُلُهَا دَآئِمٌ﴾: لا ينقطع ثمرها ونعيمها، (وظلها) أي: ظلها ظليل لا يزول. البغوي:٢/٥٣٥.\nما ميزة أكل الجنة وظلها المذكورة في الآية؟\nوَٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ يَفۡرَحُونَ بِمَآ أُنزِلَ إِلَيۡكَۖ وَمِنَ ٱلۡأَحۡزَابِ مَن يُنكِرُ بَعۡضَهُۥۚ قُلۡ إِنَّمَآ أُمِرۡتُ أَنۡ أَعۡبُدَ ٱللَّهَ وَلَآ أُشۡرِكَ بِهِۦٓۚ إِلَيۡهِ أَدۡعُواْ وَإِلَيۡهِ مَـَٔابِ ٣٦\n﴿قُلۡ إِنَّمَآ أُمِرۡتُ أَنۡ أَعۡبُدَ ٱللَّهَ﴾: وجه اتصاله بما قبله أنه جواب المنكرين ورد عليهم؛ كأنه قال: إنَّما أمرت بعبادة الله وتوحيده؛ فكيف تنكرون هذا؟!. ابن جزي:١/٤٣٨.\nالقرآن أمر بأمر موافق للفطرة، فما هو؟\nقُلۡ إِنَّمَآ أُمِرۡتُ أَنۡ أَعۡبُدَ ٱللَّهَ وَلَآ أُشۡرِكَ بِهِۦٓۚ\nومن بلاغة الجدل القرآني أنه لم يأت بذلك من أول الكلام؛ بل أتى به متدرّجًا فيه، فقال: ﴿أَنۡ أَعۡبُدَ ٱللَّهَ﴾؛ لأنه لا ينازع في ذلك أحد من أهل الكتاب ولا المشركين، ثم جاء بعده: ﴿وَلَآ أُشۡرِكَ بِهِۦٓۚ﴾ لإبطال إشراك المشركين، وللتعريض بإبطال إلاهية عيسى -عليه السلام-. ابن عاشور:١٣/١٥٨.\nيتوصل القرآن الكريم إلى تقرير التوحيد ونفي الشرك بتدرج؛ بين ذلك.\nوَكَذَٰلِكَ أَنزَلۡنَٰهُ حُكۡمًا عَرَبِيّٗاۚ\nكمال من جهة معانيه ومقاصده؛ وهو كونه حكمًا، وكمال من جهة ألفاظه؛ وهو المكنّى عنه بكونه عربيًا. ابن عاشور:١٣/١٦٠.\nذكرت الآية الكريمة كمالَين للقرآن الكريم، فما هما؟\nوَلَئِنِ ٱتَّبَعۡتَ أَهۡوَآءَهُم بَعۡدَ مَا جَآءَكَ مِنَ ٱلۡعِلۡمِ مَا لَكَ مِنَ ٱللَّهِ مِن وَلِيّٖ وَلَا وَاقٖ ٣٧\n﴿وَلَئِنِ ٱتَّبَعۡتَ أَهۡوَآءَهُم﴾ أي: أهواء المشركين في عبادة ما دون الله... ﴿مَا لَكَ مِنَ ٱللَّهِ مِن وَلِيٍّ﴾ أي: ناصر ينصرك، ﴿وَلَا وَاقٍ﴾: يمنعك من عذابه. والخطاب للنبي والمراد الأمة. القرطبي:١٢/٨٤.\nما العقوبة والجزاء اللذان ينتظران من اتبع أهواء الشرق والغرب من الكفار؟\nيَمۡحُواْ ٱللَّهُ مَا يَشَآءُ وَيُثۡبِتُۖ وَعِندَهُۥٓ أُمُّ ٱلۡكِتَٰبِ ٣٩\n﴿يَمۡحُواْ ٱللَّهُ﴾ أي: الملك الأعظم، ﴿مَا يَشَآءُ﴾ أي: محوه من الشرائع والأحكام وغيرها بالنسخ؛ فيرفعه، (ويثبت) ما يشاء إثباته من ذلك بأن يقره ويمضي حكمه،... كل ذلك بحسب المصالح التابعة لكل زمن؛ فإنه العالم بكل شيء، وهو الفعال لما يريد، لا اعتراض عليه. البقاعي:٤/١٦٠.\nما الحكمة من نسخ بعض الأحكام، وإثبات بعضها؟\nأَوَ لَمۡ يَرَوۡاْ أَنَّا نَأۡتِي ٱلۡأَرۡضَ نَنقُصُهَا مِنۡ أَطۡرَافِهَاۚ\nونقصها هو بما يفتح الله على المسلمين منها؛ والمعنى: أولم يروا ذلك فيخافوا أن نمكنك منهم؟! وقيل: الأرض جنس؛ ونقصها بموت الناس، وهلاك الثمرات، وخراب البلاد، وشبه ذلك. ابن جزي:١/٤٣٩.\nفي نقص الأرض من أطرافها معانٍ، بيّنها."],[255,"§الرعد ، إبراهيم\nwords\nوَيَبغُونَهَا عِوَجًايُرِيدُونَهَا مُعوَجَّةً؛ مُوَافِقَةً لأِهوَائِهِم.\nبِأَيَّامِ اللهِنِعَمِهِ وَنِقَمِهِ الَّتِي قَدَّرَهَا فِي الأَيَّامِ.\ndeeds\nقل إذا أصبحت وإذا أمسيت ثلاث مرات: \"رضيتُ بالله ربًا، وبالإسلام دينًا، وبمحمد نبيًا\".\nاقرأ سورة من القرآن، واستخرج ما فيها من الفوائد التي تنير لك الطريق.\nتذكــر أيـامًا عصيبةً مـرت على المجتمـع، وتعـاون مـع من حـولك في استـخـراج فـوائـد مـن ذلك الحـدث، وأرســلها في رسـالة لـمن تـعرف.\nguid\nإذا اشتبه عليك أمر ولم تعرف الحق فيه فبادر بقراءة القرآن الكريم؛ لعل الله تعالى أن يهديك للحق والرشد.\nلا تحصل الهداية إلا بإذن الله تعالى ومعونته وتوفيقه.\nتيسير الفهم والتعلم سمة من سمات الشريعة.\nrefl\nقُلۡ كَفَىٰ بِٱللَّهِ شَهِيدَۢا بَيۡنِي وَبَيۡنَكُمۡ وَمَنۡ عِندَهُۥ عِلۡمُ ٱلۡكِتَٰبِ ٤٣\nوإنَّما أمر الله باستشهاد أهل الكتاب لأنهم أهل هذا الشأن، وكل أمر إنَّما يستشهد فيه أهله ومن هم أعلم به من غيرهم، بخلاف من هو أجنبي عنه؛ كالأميين من مشركي العرب وغيرهم، فلا فائدة من استشهادهم؛ لعدم خبرتهم ومعرفتهم. السعدي:٤٢٠-٤٢١.\nلماذا استشهد أهل الكتاب خاصة دون غيرهم؟\nكِتَٰبٌ أَنزَلۡنَٰهُ إِلَيۡكَ لِتُخۡرِجَ ٱلنَّاسَ مِنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ بِإِذۡنِ رَبِّهِمۡ\n﴿لِتُخۡرِجَ ٱلنَّاسَ﴾ أي: بالكتاب؛ وهو القرآن. ﴿مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِۖ﴾ أي: من ظلمات الكفر والضلالة والجهل إلى نور الإيمان والعلم، وهذا على التمثيل؛ لأن الكفر بمنزلة الظلمة، والإسلام بمنزلة النور. القرطبي:١٢/١٠٢.\nكيف يفعل من أراد إخراج الظلمة من قلبه، وإدخال النور فيه؟\nإِلَىٰ صِرَٰطِ ٱلۡعَزِيزِ ٱلۡحَمِيدِ ١\nوفي ذكر ﴿ٱلۡعَزِيزِ ٱلۡحَمِيدِ﴾ بعد ذكر الصراط الموصل إليه إشارةٌ إلى أن من سلكه فهو عزيز بعز الله، قوي ولو لم يكن له أنصار إلا الله، محمود في أموره حسن العاقبة. السعدي:٤٢١.\nماذا تفيد من إضافة الصراط إلى اسمي الله: (العزيز) و(الحميد)؟\nٱلَّذِينَ يَسۡتَحِبُّونَ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا عَلَى ٱلۡأٓخِرَةِ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَيَبۡغُونَهَا عِوَجًاۚ أُوْلَٰٓئِكَ فِي ضَلَٰلِۢ بَعِيدٖ ٣\nوكل من آثر الدنيا وزهرتها، واستحب البقاء في نعيمها على النعيم في الآخرة، وصد عن سبيل الله... فهو داخل في هذه الآية، وقد قال -صلى الله عليه وسلم-: «إن أخوف ما أخاف على أمتي الأئمة المضلون»، وهو حديث صحيح، وما أكثر ما هم في هذه الأزمان، والله المستعان. وقيل: (يستحبون) أي: يلتمسون الدنيا من غير وجهها. القرطبي:١٢/١٠٤.\nما صفات من ذمهم الله تعالى في الآية لنحذرهم؟\nوَمَآ أَرۡسَلۡنَا مِن رَّسُولٍ إِلَّا بِلِسَانِ قَوۡمِهِۦ\nويستدل بهذه الآية الكريمة على أن علوم العربية الموصلة إلى تبيين كلامه وكلام رسوله أمور مطلوبة محبوبة لله؛ لأنه لا يتم معرفة ما أنزل على رسوله إلا بها. السعدي:٤٢١.\nكيف يستدل بهذه الآية على أهمية تعلم اللغة العربية؟\nوَذَكِّرۡهُم بِأَيَّىٰمِ ٱللَّهِۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّكُلِّ صَبَّارٖ شَكُورٖ ٥\n(وذكرهم بأيام الله) أي: عقوباته للأمم المتقدمة، وقيل: إنعامه على بني إسرائيل. واللفظ يعم النعم والنقم، وعبر عنها بالأيام؛ لأنها كانت في أيام، وفي ذلك تعظيم لها، كقولهم يوم كذا ويوم كذا. ابن جزي:١/٤٤١.\nمن أسباب تقوية الإيمان قراءة تاريخ الأمم السابقة وما جرى لهم؛ وضح ذلك.\nوَذَكِّرۡهُم بِأَيَّىٰمِ ٱللَّهِۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّكُلِّ صَبَّارٖ شَكُورٖ ٥\nقال تعالى: ﴿إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٍ لِّكُلِّ صَبَّارٍ شَكُورٍ﴾ في غير موضع؛ فالصبر والشكر على ما يقدره الرب على عبده من السراء والضراء، من النعم والمصائب، من الحسنات التي يبلوه بها والسيئات؛ فعليه أن يتلقى المصائب بالصبر، والنعم بالشكر، ومن النعم ما ييسره له من أفعال الخير، ومنها ما هي خارجة عن أفعاله. ابن تيمية:٤/١٠٧.\nينبغي أن يتعامل المؤمن مع ما يقدره الله تعالى بالصبر و الشكر، بين ذلك."],[256,"§إبراهيم\nwords\nيَسُومُونَكُميُذِيقُونَكُم.\nتَأَذَّنَأَعلَمَ إِعلامًا مُؤَكَّدًا.\nفَرَدُّوا أَيدِيَهُم فِي أَفوَاهِهِمعَضُّوا أَيدِيَهُم؛ تَغَيُّظًا عَلَى الرُّسُلِ وَدِينِهِم.\nفَاطِرِمُنشِئِ ومُبدِعِ.\ndeeds\nتأمل حوار الرسل مع المدعوين، واستخرج ثلاث فوائد من ذلك لتعينك على اتباع سنتهم في الحوار.\nعَدِّد خمسًا من أكبر نِعم الله عليك في يومك هذا، وأكثر من شكر الله عليها، ثم قل: \"اللهم ما أصبح بي من نعمة أو بأحد من خلقك فمنك وحدك لا شريك لك؛ فلك الحمد ولك الشكر\".\nأرسل رسالة تذكـر فيـها بشكر نعمة الله، والتحذير من زوالـها.\nguid\nكفر النعم سبب زوالها.\nشكر النعم باللسان والقلب والجوارح سببٌ لزيادتها.\nعلى الداعية أن يكون واثقًا في خطابه ليكون ذلك أبلغ عند السامع.\nrefl\nإِذۡ أَنجَىٰكُم مِّنۡ ءَالِ فِرۡعَوۡنَ يَسُومُونَكُمۡ سُوٓءَ ٱلۡعَذَابِ وَيُذَبِّحُونَ أَبۡنَآءَكُمۡ وَيَسۡتَحۡيُونَ نِسَآءَكُمۡۚ وَفِي ذَٰلِكُم بَلَآءٞ مِّن رَّبِّكُمۡ عَظِيمٞ ٦\nالبلاء: الاختبار، والبلاء هنا: المصيبة بالشر؛ سمي باسم الاختبار لأنه اختبار لمقدار الصبر. ابن عاشور:١٣/١٩٢.\nما المقصود من الابتلاء؟\nوَإِذۡ تَأَذَّنَ رَبُّكُمۡ لَئِن شَكَرۡتُمۡ لَأَزِيدَنَّكُمۡۖ وَلَئِن كَفَرۡتُمۡ إِنَّ عَذَابِي لَشَدِيدٞ ٧\nقال الربيع: \"﴿لَئِن شَكَرۡتُمۡ﴾ إنعامي (لأزيدنكم) من فضلي\"، وقال الحسن: \"﴿لَئِن شَكَرۡتُمۡ﴾ نعمتي (لأزيدنكم) من طاعتي\"، وقال ابن عباس -رضي الله عنهما-: \"لئن وحدتم وأطعتم لأزيدنكم من الثواب\"؛ والمعنى متقارب في هذه الأقوال. القرطبي:١٢/١٠٩.\nما الذي يناله العبد إذا داوم على شكر الله -سبحانه وتعالى-؟\nوَإِذۡ تَأَذَّنَ رَبُّكُمۡ لَئِن شَكَرۡتُمۡ لَأَزِيدَنَّكُمۡۖ وَلَئِن كَفَرۡتُمۡ إِنَّ عَذَابِي لَشَدِيدٞ ٧\n﴿لَئِن شَكَرۡتُمۡ﴾: وأكَّدَه لما للأنفس من التكذيب بمثل ذلك، (لأزيدنكم) من نِعَمي؛ فإن الشكر قيد الموجود وصيد المفقود. البقاعي:٤/١٧٢.\nما فائدة شكر النعم؟\nوَقَالَ مُوسَىٰٓ إِن تَكۡفُرُوٓاْ أَنتُمۡ وَمَن فِي ٱلۡأَرۡضِ جَمِيعٗا فَإِنَّ ٱللَّهَ لَغَنِيٌّ حَمِيدٌ ٨\nولما كان مَن حثَّ على شيء وأثاب عليه، أو نهى عنه وعاقب على فعله، يكون لغرض له؛ بيَّن أن الله سبحانه متعالٍ عن أن يلحقه ضر أو نفع، وأن ضر ذلك ونفعه خاص بالعبد؛ فقال تعالى حاكيًا عنه: ﴿وَقَالَ مُوسَىٰ﴾. البقاعي:٤/١٧٢.\nماذا تفيد من هذه الآية؟\nوَقَالَ مُوسَىٰٓ إِن تَكۡفُرُوٓاْ أَنتُمۡ وَمَن فِي ٱلۡأَرۡضِ جَمِيعٗا فَإِنَّ ٱللَّهَ لَغَنِيٌّ حَمِيدٌ ٨\nووجه الاهتمام بها أن أكثر الكفار يحسبون أنهم يحسنون إلى الله بإيمانهم، وأن أنبياءهم -حين يلحون عليهم بالإيمان- إنَّما يبتغون بذلك تعزيز جانبهم، والحرص على مصحلتهم؛ فلما وعدهم على الشكر بالزيادة وأوعدهم على الكفر بالعقوبة، خشي أن يحسبوا ذلك لانتفاع المثيب بما أثاب عليه ولتضرره مما عاقب عليه؛ فنبههم إلى هذا الخاطر الشيطاني حتى لا يسري إلى نفوسهم، فيكسبهم إدلالًا بالإيمان والشكر والإقلاع عن الكفر. ابن عاشور:١٣/١٩٢.\nما وجه الاهتمام ببيان غنى الله تعالى عن خلقه؟\nجَآءَتۡهُمۡ رُسُلُهُم بِٱلۡبَيِّنَٰتِ فَرَدُّوٓاْ أَيۡدِيَهُمۡ فِيٓ أَفۡوَٰهِهِمۡ وَقَالُوٓاْ إِنَّا كَفَرۡنَا بِمَآ أُرۡسِلۡتُم بِهِۦ وَإِنَّا لَفِي شَكّٖ مِّمَّا تَدۡعُونَنَآ إِلَيۡهِ مُرِيبٖ ٩\n﴿فَرَدُّوٓاْ أَيۡدِيَهُمۡ فِيٓ أَفۡوَٰهِهِمۡ﴾: فيه ثلاثة أقوال؛ أحدها: أن الضمائر لقوم الرسل، والمعنى: أنهم ردوا أيديهم في أفواه أنفسهم غيظًا من الرسل؛ كقوله: ﴿عَضُّواْ عَلَيۡكُمُ ٱلۡأَنَامِلَ مِنَ ٱلۡغَيۡظِ﴾ [آل عمران: ١١٩]، أو استهزاء وضحكا؛ كمن غلبه الضحك فوضع يده على فمه. والثاني: أن الضمائر لهم، والمعنى: أنهم ردوا أيديهم في أفواه أنفسهم؛ إشارة على الأنبياء بالسكوت. والثالث: أنهم ردوا أيديهم في أفواه الأنبياء تسكيتًا لهم. ابن جزي:١/٤٤٢.\nما الذي يفيده الداعية من مواقف الأمم الضالة من رسلهم؟\nقَالَتۡ رُسُلُهُمۡ أَفِي ٱللَّهِ شَكّٞ\nأفِي وجوده شك؟! فإن الفطر شاهدة بوجوده، ومجبولة على الإقرار به؛ فإن الاعتراف به ضروري في الفطر السليمة. ابن كثير:٢/٥٠٦.\nلماذا استهجنت الرسل الشك في وجود الله -سبحانه وتعالى-؟"],[257,"§إبراهيم\nwords\nمَقَامِيمَوقِفَهُ بَينَ يَدَيَّ لِلحِسَابِ.\nوَاستَفتَحُوااستَنصَرَ الرُّسُلُ بِاللهِ عَلَى الظَّالِمِينَ.\nوَخَابَهَلَكَ، وَخَسِرَ.\nصَدِيدٍالقَيحِ وَالدَّمِ الَّذِي يَسِيلُ مِن أَجسَادِ أَهلِ النَّارِ.\nيَتَجَرَّعُهُيُحَاوِلُ ابتِلاعَهُ.\ndeeds\nتضرع إلى الله سائلًا أن يمن عليك بما من به على الصالحين من العلم والعمل والحكمة والتوفيق.\nسل الله تعالى أن يهلك الظالمين بالظالمين، وأن يخرج المسلمين من بينهم سالمين.\nراجع أعمالك قبل أن تخسرها يوم القيامة: هل تسرّب إليها رياء أو شرك أو بدعة؟\nguid\nاعلم أن من أهم واجبات الداعية اليقين بوعد الله تعالى، وحسن التوكل عليه سبحانه.\nوعد سبحانه المؤمنين بالاستخلاف في الأرض من بعد أن كانوا ضعفاء أذلة، وتحقق ذلك للصحابة والتابعين -رضي الله عنهم-.\nالشرك يحبط الأعمال فلا يستفيد منها صاحبها يوم القيامة.\nrefl\nقَالَتۡ لَهُمۡ رُسُلُهُمۡ إِن نَّحۡنُ إِلَّا بَشَرٞ مِّثۡلُكُمۡ وَلَٰكِنَّ ٱللَّهَ يَمُنُّ عَلَىٰ مَن يَشَآءُ مِنۡ عِبَادِهِۦۖ\n﴿وَلَٰكِنَّ ٱللَّهَ يَمُنُّ عَلَىٰ مَن يَشَآءُ مِنۡ عِبَادِهِۦۖ﴾ أي: يتفضل عليه... بالتوفيق والحكمة والمعرفة والهداية. القرطبي:١٢/١١٥.\nالتساوي في الشكل والمظهر لا يلزم منه التساوي في العلم والحكمة، وضح ذلك من الآية.\nوَمَا لَنَآ أَلَّا نَتَوَكَّلَ عَلَى ٱللَّهِ وَقَدۡ هَدَىٰنَا سُبُلَنَاۚ وَلَنَصۡبِرَنَّ عَلَىٰ مَآ ءَاذَيۡتُمُونَاۚ وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ ٱلۡمُتَوَكِّلُونَ ١٢\nواعلم أن الرسل -عليهم الصلاة والسلام- توكلهم في أعلى المطالب وأشرف المراتب؛ وهي التوكل على الله في إقامة دينه ونصره، وهداية عبيده، وإزالة الضلال عنهم؛ وهذا أكمل ما يكون من التوكل. السعدي:٤٢٣.\nما أرقى مراتب التوكل وأكملها؟\nوَقَالَ ٱلَّذِينَ كَفَرُواْ لِرُسُلِهِمۡ لَنُخۡرِجَنَّكُم مِّنۡ أَرۡضِنَآ أَوۡ لَتَعُودُنَّ فِي مِلَّتِنَاۖ فَأَوۡحَىٰٓ إِلَيۡهِمۡ رَبُّهُمۡ لَنُهۡلِكَنَّ ٱلظَّٰلِمِينَ ١٣\nخيَّر الكفار الرسل بين أن يعودوا في ملتهم أو يخرجوهم من أرضهم، وهذه سيرة الله تعالى في رسله وعباده؛ ألا ترى إلى قوله: ﴿وَإِن كَادُواْ لَيَسۡتَفِزُّونَكَ مِنَ ٱلۡأَرۡضِ لِيُخۡرِجُوكَ مِنۡهَا﴾ [الإسراء: ٧٦]. القرطبي:١٢/١١٦.\nطرد الدعاة من بلدانهم وإخراجهم من أرضهم؛ هل هذه عادة جديدة للطغاة أم قديمة؟\nوَلَنُسۡكِنَنَّكُمُ ٱلۡأَرۡضَ مِنۢ بَعۡدِهِمۡۚ ذَٰلِكَ لِمَنۡ خَافَ مَقَامِي وَخَافَ وَعِيدِ ١٤\n﴿ذَٰلِكَ لِمَنۡ خَافَ مَقَامِي وَخَافَ وَعِيدِ﴾:... وفي الجمع بينهما دلالة على أن من حق المؤمن أن يخاف غضب ربه وأن يخاف وعيده، والذين يخافون غضب الله ووعيده هم المتقون الصالحون. ابن عاشور:١٣/٢٠٨.\nأشارت الآية الكريمة إلى صفة من صفات المؤمنين، فما هي؟\nوَٱسۡتَفۡتَحُواْ وَخَابَ كُلُّ جَبَّارٍ عَنِيدٖ ١٥\nالجبار: المتكبر الذي لا يرى لأحد عليه حقًا، والعنيد: المعاند للحق والمجانب له. القرطبي:١٢/١١٧.\nمن أولى الناس بالخيبة وسوء الخاتمة؟\nوَيَأۡتِيهِ ٱلۡمَوۡتُ مِن كُلِّ مَكَانٖ\nقال إبراهيم التيمي: \"يأتيه من كل مكان من جسده، حتى من أطراف شعره؛ للآلام التي في كل مكان من جسده\"، وقال الضحاك: \"إنه ليأتيه الموت من كل ناحية ومكان، حتى من إبهام رجليه\". القرطبي:١٢/١٢٢.\nكيف يأتي الموت للجبابرة من أهل النار من كل مكان؟ وما دلالة ذلك؟\nمَّثَلُ ٱلَّذِينَ كَفَرُواْ بِرَبِّهِمۡۖ أَعۡمَٰلُهُمۡ كَرَمَادٍ ٱشۡتَدَّتۡ بِهِ ٱلرِّيحُ فِي يَوۡمٍ عَاصِفٖۖ لَّا يَقۡدِرُونَ مِمَّا كَسَبُواْ عَلَىٰ شَيۡءٖۚ ذَٰلِكَ هُوَ ٱلضَّلَٰلُ ٱلۡبَعِيدُ ١٨\nبنوا أعمالهم على غير أساس صحيح؛ فانهارت، وعدموها أحوج ما كانوا إليها. ابن كثير:٢/٥٠٨.\nمن خلال الآية: بين خطورة التساهل بالبدع والشركيات."],[258,"§إبراهيم\nwords\nسَوَاءٌ عَلَينَايَستَوِي عَلَينَا وَعَلَيكُم.\nمَحِيصٍمَهرَبٍ.\nسُلطَانٍحُجَّةٍ وَقُوَّةٍ أَقهَرُكُم بِهَا عَلَى اتِّبَاعِي.\nبِمُصرِخِكُمبِمُغِيثِكُم.\nكَفَرتُتَبَرَّأتُ.\ndeeds\nلا تأمن الشيطان، وأكثر من الاستعاذة بالله منه؛ فإنه سبب كل بلاء.\nاجلس مع نفسك جلسة محاسبة، وراجع ما مضى من عملك.\nاقرأ شرحًا لكلمة التوحيد: ﴿لَآ إِلَٰهَ إِلَّا ٱللَّهُ﴾، وشروطها، وأركانها، وتأمل في معانيها.\nguid\nموقف الضعفاء من المتكبرين يوم القيامة يجعلك لا تجامل أحدًا في أمر الدين، ويحملك على اتباع الشرع لا الأشخاص.\nأكثر ما يتمناه المشركون يوم القيامة: الهداية؛ فاحرص عليها في الدنيا ما دمت تقدر عليها.\nاصبر على الطاعات، وعن المعاصي قبل أن يأتي يومٌ لا ينفع فيه صبرٌ أو جزع.\nrefl\nأَلَمۡ تَرَ أَنَّ ٱللَّهَ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ بِٱلۡحَقِّۚ إِن يَشَأۡ يُذۡهِبۡكُمۡ وَيَأۡتِ بِخَلۡقٖ جَدِيدٖ ١٩\n﴿إِن يَشَأۡ يُذۡهِبۡكُمۡ وَيَأۡتِ بِخَلۡقٍ جَدِيدٍ﴾ أي: هو قادر على الإفناء كما قدر على إيجاد الأشياء؛ فلا تعصوه، فإنكم إن عصيتموه ﴿يُذۡهِبۡكُمۡ وَيَأۡتِ بِخَلۡقٍ جَدِيدٍ﴾ أفضل وأطوع منكم. القرطبي:١٢/١٢٥.\nما العقوبة التي ستحل بنا إن تركنا طاعة الله، وآثرنا شهوات أنفسنا؟\nوَقَالَ ٱلشَّيۡطَٰنُ لَمَّا قُضِيَ ٱلۡأَمۡرُ إِنَّ ٱللَّهَ وَعَدَكُمۡ وَعۡدَ ٱلۡحَقِّ\nفقام فيهم إبليس -لعنه الله- يومئذ خطيبًا؛ ليزيدهم حزنًا إلى حزنهم، وغبنًا إلى غبنهم، وحسرة إلى حسرتهم. ابن كثير:٢/٥١٠.\nما الحكمة من خطبة إبليس في المعذبين في النار؟\nوَقَالَ ٱلشَّيۡطَٰنُ لَمَّا قُضِيَ ٱلۡأَمۡرُ إِنَّ ٱللَّهَ وَعَدَكُمۡ وَعۡدَ ٱلۡحَقِّ وَوَعَدتُّكُمۡ فَأَخۡلَفۡتُكُمۡۖ\nحكى الله تعالى عنه ما سيقوله في ذلك الوقت ليكون تنبيهًا للسامعين، وحثًا لهم على النظر في عاقبتهم، والاستعداد لما لا بد منه، وأن يتصوروا ذلك المقام الذي يقول فيه الشيطان ما يقول؛ فيخافوا، ويعملوا ما ينفعهم هناك. الألوسي:١٤/٢٦٦.\nما الحكمة من إعلامنا بما سيقوله الشيطان لأتباعه يوم القيامة؟\nوَمَا كَانَ لِيَ عَلَيۡكُم مِّن سُلۡطَٰنٍ إِلَّآ أَن دَعَوۡتُكُمۡ فَٱسۡتَجَبۡتُمۡ لِيۖ\nوهم الذين سلطوه على أنفسهم بموالاته والالتحاق بحزبه؛ ولهذا ليس له سلطان على الذين آمنوا وعلى ربهم يتوكلون. السعدي:٤٢٥.\nما صفة من ثبت عليه سلطان الشيطان؟\nوَمَا كَانَ لِيَ عَلَيۡكُم مِّن سُلۡطَٰنٍ إِلَّآ أَن دَعَوۡتُكُمۡ فَٱسۡتَجَبۡتُمۡ لِيۖ\nواعلم أن الله ذكر في هذه الآية أنه ليس له سلطان، وقال في آية أخرى: ﴿إِنَّمَا سُلۡطَٰنُهُۥ عَلَى ٱلَّذِينَ يَتَوَلَّوۡنَهُۥ وَٱلَّذِينَ هُم بِهِۦ مُشۡرِكُونَ﴾ [النحل: ١٠٠]؛ فالسلطان الذي نفاه عنه هو سلطان الحجة والدليل، فليس له حجة أصلًا على ما يدعو إليه، وإنَّما نهاية ذلك أن يقيم لهم من الشبه والتزيينات ما به يتجرؤون على المعاصي. وأمَّا السلطان الذي أثبته فهو التسلط بالإغراء على المعاصي لأوليائه؛ يؤزهم إلى المعاصي أزًا. السعدي:٤٢٥.\nتَحِيَّتُهُمۡ فِيهَا سَلَٰمٌ ٢٣\nيسلم بعضهم على بعض، وتسلم الملائكة عليهم. القرطبي:٢/٥٥٥.\nالسلام أفضل أنواع التحية، ما الدليل على ذلك؟\nأَلَمۡ تَرَ كَيۡفَ ضَرَبَ ٱللَّهُ مَثَلٗا كَلِمَةٗ طَيِّبَةٗ كَشَجَرَةٖ طَيِّبَةٍ أَصۡلُهَا ثَابِتٞ وَفَرۡعُهَا فِي ٱلسَّمَآءِ ٢٤\nفالكلمة الطيبة: التوحيد، وهي كالشجرة، والأعمال ثمارها في كل وقت. ابن تيمية:٤/١١٠.\nالكلمة الطيبة هي التوحيد، والأعمال ثمارها، بين ذلك."],[259,"§إبراهيم\nwords\nاجتُثَّتاقتُلِعَت.\nقَرَارٍأَصلٍ ثَابِتٍ.\nالبَوَارِالهَلاكِ.\nخِلاَلٌصَدَاقَةٌ.\nدَائِبَينِجَارِيَينِ لا يَفتُرَانِ وَلا يَتَوَقَّفَانِ.\ndeeds\nاستخدم اليوم ضرب المثل في كلامك؛ فإن لذلك بالغ الأثر في وصول الفائدة.\nقل: \"اللهم ثبتني بالقول الثابت في الحياة الدنيا وفي الآخرة\"، واستعذ بالله تعالى من عذاب القبر.\nأقم الصلوات الخمس مع الجماعة.\nguid\nالثبات يكون في الدنيا، ويكون في الآخرة، وهو منة من الله سبحانه؛ فمن ثبَّـتَه الله في الدنيا ثبَّـتَه في الآخرة.\nالظلم من العبد سبب لإضلال الله تعالى له؛ فاجتنب الظلم، وخاصة ظلم الضعفاء؛ من النساء والأيتام والخدم والعمال والمساكين.\nالعاقل يعرف حقيقة متاع الدنيا، وأنه إلى زوال وفناء؛ فلا يشغله عن أعمال الآخرة.\nrefl\nتُؤۡتِيٓ أُكُلَهَا كُلَّ حِينِۢ بِإِذۡنِ رَبِّهَاۗ\nوالحكمة في تمثيل الإيمان بالشجرة هي أن الشجرة لا تكون شجرة إلا بثلاثة أشياء: عرق راسخ، وأصل قائم، وفرع عال؛ كذلك الإيمان لا يتم إلا بثلاثة أشياء: تصديق القلب، وقول اللسان، وعمل بالأبدان. البغوي:٢/٥٥٦.\nما الحكمة في تمثيل إيمان العبد بالشجرة؟\nيُثَبِّتُ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ بِٱلۡقَوۡلِ ٱلثَّابِتِ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا\nفيثبتهم الله في الحياة الدنيا عند ورود الشبهات بالهداية إلى اليقين، وعند عروض الشهوات بالإرادة الجازمة على تقديم ما يحبه الله على هوى النفس ومراداتها. السعدي:٤٢٥.\nبيّن بعض صور تثبيت الله للعبد في الحياة الدنيا.\nيُثَبِّتُ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ بِٱلۡقَوۡلِ ٱلثَّابِتِ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَفِي ٱلۡأٓخِرَةِۖ\nفيثبتهم الله في الآخرة عند الموت بالثبات على الدين الإسلامي والخاتمة الحسنة، وفي القبر عند سؤال الملكين للجواب الصحيح. السعدي:٤٢٦.\nبيّن بعض صور تثبيت الله للعبد في الآخرة.\nوَيُضِلُّ ٱللَّهُ ٱلظَّٰلِمِينَۚ وَيَفۡعَلُ ٱللَّهُ مَا يَشَآءُ ٢٧\nأي: عن حجتهم في قبورهم؛ كما ضلوا في الدنيا بكفرهم، فلا يلقنهم كلمة الحق؛ فإذا سُئلوا في قبورهم قالوا: لا ندري، فيقولان: لا دريت ولا تليت، وعند ذلك يضرب بالمقامع. القرطبي:١٢/١٤٠.\nكيف يكون إضلال الظالمين يوم القيامة؟\nأَلَمۡ تَرَ إِلَى ٱلَّذِينَ بَدَّلُواْ نِعۡمَتَ ٱللَّهِ كُفۡرٗا وَأَحَلُّواْ قَوۡمَهُمۡ دَارَ ٱلۡبَوَارِ ٢٨\nومن استقرأ أحوال العالم تبين له أن الله لم ينعم على أهل الأرض نعمة أعظم من إنعامه بإرساله -صلى الله عليه وسلم-، وإن الذين ردوا رسالته هم من قال الله فيهم: (ألم تر إلى الذين بدلوا نعمة الله كفرًا وأحلوا قومهم دار البوار). ابن تيمية:٤/١١٦- ١١٧.\nلم ينعم الله تعالى على خلقه نعمة أعظم من رسالة محمد -صلى الله عليه وسلم-، كيف ذلك؟\nقُلۡ تَمَتَّعُواْ فَإِنَّ مَصِيرَكُمۡ إِلَى ٱلنَّارِ ٣٠\n﴿قُلۡ تَمَتَّعُواْ﴾: وعيد لهم، وهو إشارة إلى تقليل ما هم فيه من ملاذ الدنيا؛ إذ هو منقطع. القرطبي:١٢/١٤٢.\nلمَ سميت زينة الدنيا متاعًا؟\nقُل لِّعِبَادِيَ ٱلَّذِينَ ءَامَنُواْ يُقِيمُواْ ٱلصَّلَوٰةَ\nوالمراد بإقامتها هو: المحافظة على وقتها، وحدودها، وركوعها، وخشوعها، وسجودها. ابن كثير:٢/٥١٩.\nما المراد بإقامة الصلاة في هذه الآية؟"],[260,"§إبراهيم\nwords\nتَهوِي إِلَيهِمتَمِيلُ إِلَيهِم، وَتَحِنُّ.\nتَشخَصُتَرتَفِعُ عُيُونُهُم فِيهِ، وَلا تَغمَضُ.\ndeeds\nتذكر ظلمًا وقع منك، وتحلل منه قبل أن تتمنى ولا تستطيع.\nادع الله بأدعية إبراهيم -عليه السلام-.\nادع الله أن يرزقك الذرية الصالحة.\nguid\nلا تستطيع أن تعدد نعم الله تعالى عليك، فضلًا عن أن تشكرها، ولكن لا يزال لسانك رطبًا من ذكر الله لاهجًا بشكره.\nعلاقة الإيمان والتوحيد أولى من علاقة الرحم والنسب.\nالحفاظ على أمن البلد من أول أمنيات الصالحين والدعاة.\nrefl\nوَءَاتَىٰكُم مِّن كُلِّ مَا سَأَلۡتُمُوهُۚ وَإِن تَعُدُّواْ نِعۡمَتَ ٱللَّهِ لَا تُحۡصُوهَآۗ\n﴿لَا تُحۡصُوهَآۗ﴾: ولا تطيقوا عدها، ولا تقوموا بحصرها لكثرتها؛ كالسمع، والبصر، وتقويم الصور، إلى غير ذلك من العافية والرزق؛ نِعَمٌ لا تحصى. القرطبي:١٢/١٤٥.\nهل تطيق أن تحصي نعم الله عليك؟ ولماذا؟\nوَإِذۡ قَالَ إِبۡرَٰهِيمُ رَبِّ ٱجۡعَلۡ هَٰذَا ٱلۡبَلَدَ ءَامِنٗا\nفاستجاب الله دعاءه شرعًا وقدرًا، فحرَّمه الله في الشرع، ويَسَّرَ من أسباب حرمته قدرًا ما هو معلوم، حتى إِنه لَم يُرِدهُ ظالم بسوء إلا قصمه الله؛ كما فعل بأصحاب الفيل وغيرهم. السعدي:٤٢٦.\nما صور استجابة الله دعاء إبراهيم -عليه السلام-؟\nوَمَنۡ عَصَانِي فَإِنَّكَ غَفُورٞ رَّحِيمٞ ٣٦\nوهذا من شفقة الخليل -عليه الصلاة والسلام-؛ حيث دعا للعاصين بالمغفرة والرحمة من الله. السعدي:٤٢٧.\nبيّن رحمة الأنبياء بأقوامهم من خلال الآية، وماذا يفيد الداعية من هذا؟\nرَبَّنَا لِيُقِيمُواْ ٱلصَّلَوٰةَ\nأي: اجعلهم موحدين، مقيمين الصلاة؛ لأن إقامة الصلاة من أخص وأفضل العبادات الدينية، فمن أقامها كان مقيمًا لدينه. السعدي:٤٢٧.\nلماذا خَصَّ إبراهيم الصلاة من بين سائر العبادات حينما دعا لذريته؟\nٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي وَهَبَ لِي عَلَى ٱلۡكِبَرِ إِسۡمَٰعِيلَ وَإِسۡحَٰقَۚ إِنَّ رَبِّي لَسَمِيعُ ٱلدُّعَآءِ ٣٩\nوأما قول إبراهيم -عليه السلام-: ﴿إِنَّ رَبِّي لَسَمِيعُ ٱلدُّعَآءِ﴾ فالمراد بالسمع هاهنا السمع الخاص؛ وهو سمع الإجابة والقبول؛ لا السمع العام؛ لأنه سميع لكل مسموع. ابن تيمية:٤/١٢٠.\nلماذا خصص إبراهيم -عليه السلام- سمع الله تعالى بالدعاء، مع أنه سبحانه سميع لكل صوت؟\nوَلَا تَحۡسَبَنَّ ٱللَّهَ غَٰفِلًا عَمَّا يَعۡمَلُ ٱلظَّٰلِمُونَۚ إِنَّمَا يُؤَخِّرُهُمۡ لِيَوۡمٖ تَشۡخَصُ فِيهِ ٱلۡأَبۡصَٰرُ ٤٢\nأي: اصبر كما صبر إبراهيم، وأَعْلِمِ المشركين أن تأخير العذاب ليس للرضا بأفعالهم؛ بل سنة الله إمهال العصاة مدة، قال ميمون بن مهران: \"هذا وعيد للظالم، وتعزية للمظلوم\". القرطبي:١٢/١٥٧.\nهل تأخر نزول العقوبة بالظالم دليل على رضا الله تعالى عنه؟\nإِنَّمَا يُؤَخِّرُهُمۡ لِيَوۡمٖ تَشۡخَصُ فِيهِ ٱلۡأَبۡصَٰرُ ٤٢\nأي: لا تَطرَفُ؛ من شدة ما ترى من الأهوال، وما أزعجها من القلاقل. السعدي:٤٢٧.\nما الذي يُفهَمُ من فتح الناس لأعينهم وعدم إغماضها أو تحريكها يوم القيامة ؟"],[261,"§إبراهيم\nwords\nمُهطِعِينَمُسرِعِينَ.\nمُقنِعِي رُؤُوسِهِمرَافِعِي رُؤُوسِهِم.\nوَأَفئِدَتُهُم هَوَاءٌقُلُوبُهُم خَالِيَةٌ مِن شِدَّةِ الهَولِ.\nمُقَرَّنِينَ فِي الأَصفَادِمُقَيَّدِينَ بِالقُيُودِ، قَد قُرِنَت أَيدِيهِم وَأَرجُلُهُم بِالسَّلاسِلِ.\nسَرَابِيلُهُمثِيَابُهُم.\ndeeds\nأرسل رسالة تنذر فيها من عذاب الله وشدة غضبه سبحانه.\nاستعذ بالله من مكر الظالمين، وقل: \"اللهم إنا ندرأ بك في نحورهم، ونعوذ بك من شرورهم\"، وقل: \"اللهم امكر لنا، ولا تمكر علينا\".\nتأمل قصة أي ظالم ذكرت في القرآن، وكيف خطط لحرب دين الله، ثم تأمل كيف كانت نهايته.\nguid\nبينما يكون الظالم الطاغي صلبًا في عدوانه في الدنيا إذا به يبعث يوم القيامة خائفًا فزعًا قد تقطع قلبه من الهلع.\nالآثار القديمة للأمم المعذبة إنَّما هي لتذكير الناس بما حَلَّ بالأقوام من قبلنا من عذاب الاستئصال.\nلن يخلف الله وعده عن رسله وأوليائه، بل حتمًا سيأتيهم النصر والتمكين.\nrefl\nمُهۡطِعِينَ مُقۡنِعِي رُءُوسِهِمۡ لَا يَرۡتَدُّ إِلَيۡهِمۡ طَرۡفُهُمۡۖ وَأَفۡـِٔدَتُهُمۡ هَوَآءٞ ٤٣\n(مهطعين):...لا يلتفتون يمينًا ولا شمالًا، ولا يعرفون مواطن أقدامهم... ﴿لَا يَرۡتَدُّ إِلَيۡهِمۡ طَرۡفُهُمۡۖ﴾: لا ترجع إليهم أبصارهم من شدة النظر، وهي شاخصة؛ قد شغلهم ما بين أيديهم، (وأفئدتهم هواء):... خرجت قلوبهم عن صدورهم، فصارت في حناجرهم؛ لا تخرج من أفواههم، ولا تعود إلى أماكنها. البغوي:٢/٥٦٨.\nهل رأيت الظلمة وبأسهم وصلابة قلوبهم على المؤمنين في الدنيا؟ بيّن كيف يكون حالهم في القيامة.\nلَا يَرۡتَدُّ إِلَيۡهِمۡ طَرۡفُهُمۡۖ\nمديمو النظر، لا يطرفون لحظة؛ لكثرة ما هم فيه من الهول والفكر والمخافة لما يحل بهم. ابن كثير:٢/٥٢٢.\nلماذا لا يرتد للظالمين طرفهم، ولا يستطيعون إغلاق أعينهم يوم القيامة؟\nوَأَفۡـِٔدَتُهُمۡ هَوَآءٞ ٤٣\nأي: خالية من العقل والفهم؛ لفرط الحيرة والدهشة، ومنه قيل للجبان والأحمق: قلبه هواء؛ أي: لا قوة ولا رأي فيه. الألوسي:١٤/٣١٠.\nكيف يكون القلب هواءً؟\nوَضَرَبۡنَا لَكُمُ ٱلۡأَمۡثَالَ ٤٥\nأي: في بلاد ثمود ونحوها، فهلا اعتبرتم بمساكنهم بعد ما تبين لكم ما فعلنا بهم. القرطبي:١٢/١٦٣.\nما تقول لمن مر على ديار الهالكين ولم يعتبر بحالهم؟\nفَلَا تَحۡسَبَنَّ ٱللَّهَ مُخۡلِفَ وَعۡدِهِۦ رُسُلَهُۥٓۚ إِنَّ ٱللَّهَ عَزِيزٞ ذُو ٱنتِقَامٖ ٤٧\n﴿فَلَا تَحۡسَبَنَّ ٱللَّهَ مُخۡلِفَ وَعۡدِهِۦ رُسُلَهُۥٓۚ﴾ يعني: وعد النصر على الكفار. فإن قيل: هلّا قال: \"مخلف رسله وعده\"، ولِمَ قدم المفعول الثاني على الأول؟ فالجواب: أنه قدم الوعد ليعلم أنه لا يخلف الوعد أصلًا على الإطلاق، ثم قال: (رسله) ليعلم أنه إذا لم يخلف وعد أحد من الناس؛ فكيف يخلف وعد رسله وخيرة خلقه؟! فقدم الوعد أولًا بقصد الإطلاق، ثم ذكر الرسل لقصد التخصيص. ابن جزي:١/٤٤٨.\nما سبب تقديم المفعول الثاني على الأول في قوله: ﴿مُخۡلِفَ وَعۡدِهِۦ رُسُلَهُۥٓۚ﴾؟\nوَتَرَى ٱلۡمُجۡرِمِينَ يَوۡمَئِذٖ مُّقَرَّنِينَ فِي ٱلۡأَصۡفَادِ ٤٩\nيقرن كل كافر مع شيطانه في سلسلة، وقيل: مقرنة أيديهم وأرجلهم إلى رقابهم بالأصفاد والقيود. البغوي:٢/٥٧١.\nبيّن كيف يكون حشر المجرمين يوم القيامة.\nإِنَّ ٱللَّهَ سَرِيعُ ٱلۡحِسَابِ ٥١\nلأنه يعلم كل شيء، ولا يخفى عليه خافية، وإن جميع الخلق بالنسبة إلى قدرته كالواحد منهم. ابن كثير:٢/٥٢٥.\nلمَ وصف حساب الله -سبحانه وتعالى- بالسريع؟"],[262,"§الحجر\nwords\nوَيُلهِهِمُ الأَمَلُيَشغَلْهُمُ الطَّمَعُ فِي الدُّنيَا، وَطُولُ البَقَاءِ فِيهَا.\nلَو مَاهَلاَّ.\nشِيَعِ الأَوَّلِينَفِرَقِ الأُمَمِ السَّابِقِينَ.\nفَظَلُّوافَاستَمَرُّوا.\nيَعرُجُونَيَصعَدُونَ.\nسُكِّرَتسُحِرَت.\ndeeds\nاحمد الله أن هداك للإسلام، وادع الله تعالى أن يثبّتك عليه حتى تلقاه.\nزُرِ القبور، وتأمل في المصير؛ فإن زيارة القبور سنّة، وهي مما يقصر به أمل العبد.\nصمم جدولًا ترتب فيه وقتك؛ ليعينك على تحديد الأهداف، والعمل الجاد المتواصل.\nguid\nالأفلام وبرامج الجوالات الترفيهية تشغل عن العمل الصالح.\nمن مظاهر رحمة الله بالإنسان أن الإنسان يطلب نزول العذاب، والله ينزل الرحمة.\nعدم الانتفاع بالقرآن عند سماعه أو قراءته عقوبةٌ بسبب الذنوب.\nrefl\nرُّبَمَا يَوَدُّ ٱلَّذِينَ كَفَرُواْ لَوۡ كَانُواْ مُسۡلِمِينَ ٢\nقال الحسن: \"إذا رأى المشركون المؤمنين وقد دخلوا الجنة، وما رأوهم في النار؛ تمنوا أنهم كانوا مسلمين\". القرطبي:١٢/١٧٦.\nمتى يتمنى الكافر أن لو كان مسلمًا؟\nذَرۡهُمۡ يَأۡكُلُواْ وَيَتَمَتَّعُواْ وَيُلۡهِهِمُ ٱلۡأَمَلُۖ فَسَوۡفَ يَعۡلَمُونَ ٣\nطول الأمل داء عضال، ومرض مزمن، ومتى تمكن من القلب فسد مزاجه، واشتد علاجه، ولم يفارقه داء، ولا نجع فيه دواء، بل أعيا الأطباء، ويئس من برئه الحكماء والعلماء. وحقيقة الأمل: الحرص على الدنيا، والانكباب عليها، والحب لها، والإعراض عن الآخرة. القرطبي:١٢/٣٨٩.\nما الداء العظيم الذي حذر الله تعالى منه في الآية؟\nذَرۡهُمۡ يَأۡكُلُواْ وَيَتَمَتَّعُواْ وَيُلۡهِهِمُ ٱلۡأَمَلُۖ فَسَوۡفَ يَعۡلَمُونَ ٣\nوفي الآية إشارة إلى أن التلذذ والتنعم وعدم الاستعداد للآخرة والتأهب لها ليس من أخلاق مَن يطلب النجاة، وجاء عن الحسن: \"ما أطال عبدٌ الأملَ إلا أساء العمل\"... وفي بعض الآثار عن علي...: \"إنَّما أخشى عليكم اثنتين: طول الأمل، واتباع الهوى؛ فإن طول الأمل يُنسي الآخرة، واتباع الهوى يصدّ عن الحق\". الألوسي:١٤/٣٤١.\nلطول الأمل أضرار، بينها من خلال الآية.\nلَّوۡ مَا تَأۡتِينَا بِٱلۡمَلَٰٓئِكَةِ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ ٧\nفَلَمَّا لم تأت بالملائكة فلست بصادق، وهذا من أعظم الظلم والجهل: أما الظلم فظاهر؛ فإن هذا تجرؤ على الله، وتعنت بتعيين الآيات التي لم يخترها، وحصل المقصود والبرهان بدونها من الآيات الكثيرة الدالة على صحة ما جاء به. وأمَّا الجهل: فإنهم جهلوا مصلحتهم من مضرتهم؛ فليس في إنزال الملائكة خير لهم، بل لا ينزل الله الملائكة إلا بالحق الذي لا إمهال على من لم يتبعه وينقد له. السعدي:٤٢٩.\nفي طلبهم الإتيان بالملائكة ظلم وجهل، وَضِّح ذلك.\nإِنَّا نَحۡنُ نَزَّلۡنَا ٱلذِّكۡرَ\nأي: القرآن الذي فيه ذكرى لكل شيء من المسائل والدلائل الواضحة، وفيه يتذكر من أراد التذكر. السعدي:٤٢٩.\nما وجه وصف القرآن بالذكر؟\nإِنَّا نَحۡنُ نَزَّلۡنَا ٱلذِّكۡرَ وَإِنَّا لَهُۥ لَحَٰفِظُونَ ٩\nومعنى حفظه: حراسته عن التبديل والتغيير كما جرى في غيره من الكتب، فتولى الله حفظ القرآن، فلم يقدر أحد على الزيادة فيه ولا النقصان منه، ولا تبديله بخلاف غيره من الكتب؛ فإن حفظها موكول إلى أهلها؛ لقوله: ﴿بِمَا ٱسۡتُحۡفِظُواْ مِن كِتَٰبِ ٱللَّهِ﴾ [المائدة: ٤٤]. ابن جزي:١/٤٥٠.\nما الفرق بين القرآن الكريم والكتب السماوية الأخرى من حيث حفظه عن التبديل؟\nمَا نُنَزِّلُ ٱلۡمَلَٰٓئِكَةَ إِلَّا بِٱلۡحَقِّ وَمَا كَانُوٓاْ إِذٗا مُّنظَرِينَ ٨\nقال مجاهد: \"بالرسالة والعذاب\"، وأمَّا على الرُّسُل فبالحق من الأقوال، وأمَّا على المنذَرين فبالحق من الأفعال من الهلاك والنجاة. البقاعي:٤/٢٠٦.\nما الحق الذي تنزلُ الملائكةُ لأجله؟"],[263,"§الحجر\nwords\nبُرُوجًامَنَازِلَ لِلكَوَاكِبِ تَنزِلُ فِيهَا.\nرَجِيمٍمَطرُودٍ مِن رَحمَةِ اللهِ.\nاستَرَقَ السمعاختَلَسَ الوَحيَ مِنَ السَّمَاءِ الدُّنيَا.\nلَوَاقِحَتَلقَحُ السَّحَابَ؛ فَيَمتَلِئُ بِالمَاءِ.\nصَلصَالٍطِينٍ يَابِسٍ يُسمَعُ لَهُ صَوتٌ إِذَا نُقِرَ.\nحمإطين أسود.\nمسنونمتغير لونه وريحه.\nنار السمومنار شديدة الحرارة لا دخان لها.\ndeeds\nتصدّق على محتاج، أو لمؤسسة تطوعية، ولا تخش من ذي العرش إقلالًا.\nاسبق غيرك إلى عبـادة من العبادات؛ فإن المتقدم أسبق إلى الجنة.\nاقرأ قصة آدم وإبليس من كتب التفسير، ثم تأمل النقاط التي استغلها ابليس في التأثير على آدم.\nguid\nتأمل في الكواكب ونجوم السماء؛ فإن الله قد جعلها آية وزينة للناظرين.\nتأمل في الأرض وانبساطها وما فيها من أرزاق.\nلا تحزن على قلة رزقك؛ فإن الله أعلم بمصلحتك منك، وارض بما قدره الله لك.\nrefl\nوَلَقَدۡ جَعَلۡنَا فِي ٱلسَّمَآءِ بُرُوجٗا وَزَيَّنَّٰهَا لِلنَّٰظِرِينَ ١٦\nوهذا مما يدعو الناظرين إلى التأمل فيها، والنظر في معانيها، والاستدلال بها على باريها. السعدي:٤٣٠.\nالنجوم والبروج التي في السماء كيف تزيد في إيمان المؤمن؟\nوَٱلۡأَرۡضَ مَدَدۡنَٰهَا\nأي: وسعناها سَعَةً يتمكن الآدميون والحيوانات كلها على الامتداد بأرجائها، والتناول من أرزاقها، والسكون في نواحيها. السعدي:٤٣٠.\nمن إساءة الظن بالله أن يعتقد الإنسان أن أرزاق الأرض لن تكفي الناس في المستقبل، وضح هذا من الآية.\nوَلَقَدۡ عَلِمۡنَا ٱلۡمُسۡتَقۡدِمِينَ مِنكُمۡ وَلَقَدۡ عَلِمۡنَا ٱلۡمُسۡتَـٔۡخِرِينَ ٢٤ وَإِنَّ رَبَّكَ هُوَ يَحۡشُرُهُمۡۚ إِنَّهُۥ حَكِيمٌ عَلِيمٞ ٢٥\n﴿وَلَقَدۡ عَلِمۡنَا ٱلۡمُسۡتَقۡدِمِينَ مِنكُمۡ﴾ يعني: الأولين والآخرين من الناس، وذكر ذلك على وجه الاستدلال على الحشر الذي ذكر بعد ذلك في قوله: ﴿وَإِنَّ رَبَّكَ هُوَ يَحۡشُرُهُمۡۚ إِنَّهُۥ حَكِيمٌ عَلِيمٌ﴾؛ لأنه إذا أحاط بهم علمًا لم تصعب عليه إعادتهم وحشرهم. ابن جزي:١/٤٥١.\nما مناسبة مجيء قوله تعالى: ﴿وَإِنَّ رَبَّكَ هُوَ يَحۡشُرُهُمۡۚ﴾ بعد قوله: ﴿وَلَقَدۡ عَلِمۡنَا ٱلۡمُسۡتَقۡدِمِينَ مِنكُمۡ﴾؟\nوَلَقَدۡ خَلَقۡنَا ٱلۡإِنسَٰنَ مِن صَلۡصَٰلٖ مِّنۡ حَمَإٖ مَّسۡنُونٖ ٢٦ وَٱلۡجَآنَّ خَلَقۡنَٰهُ مِن قَبۡلُ مِن نَّارِ ٱلسَّمُومِ ٢٧\nوالمقصود من الآية: التنبيه على شرف آدم -عليه السلام- وطيب عنصره. ابن كثير:٢/٥٣١.\nلماذا قُرِنَ بين خلق الإنسان وخلق الجان؟\nفَإِذَا سَوَّيۡتُهُۥ وَنَفَخۡتُ فِيهِ مِن رُّوحِي فَقَعُواْ لَهُۥ سَٰجِدِينَ ٢٩\nوأمر الملائكة السجود لا ينافي تحريم السجود في الإسلام لغير الله من وجوه؛ أحدها: أن ذلك المنع لسدّ ذريعة الإشراك، والملائكة معصومون من تطرّق ذلك إليهم. وثانيها: أن شريعة الإسلام امتازت بنهاية مبالغ الحق والصلاح، فجاءت بما لم تجئ به الشرائع السالفة؛ لأن الله أراد بلوغ أتباعها أوج الكمال في المدارك. وثالثها: أن هذا إخبار عن أحوال العالم العلوي، و لا تقاس أحكامه على تكاليف عالم الدنيا. ابن عاشور:١٤/٤٥.\nأمر الملائكة بالسجود لا ينافي تحريم السجود لغير الله تعالى في الإسلام من وجوه، اذكرها.\nفَإِذَا سَوَّيۡتُهُۥ وَنَفَخۡتُ فِيهِ مِن رُّوحِي فَقَعُواْ لَهُۥ سَٰجِدِينَ ٢٩\nوإن كان مخلوقًا من طين فقد حصل له بنفخ الروح المقدسة فيه ما شرف به؛ فلهذا قال: ﴿فَإِذَا سَوَّيۡتُهُۥ وَنَفَخۡتُ فِيهِ مِن رُّوحِي فَقَعُواْ لَهُۥ سَٰجِدِينَ﴾، فعلق السجود بأن ينفخ فيه من روحه، فالموجب للتفضيل هذا المعنى الشريف الذي ليس لإبليس مثله. ابن تيمية:٤/١٢٥.\nبيّن وجه تكريم آدم -عليه السلام- على غيره من خلال الآية.\nفَسَجَدَ ٱلۡمَلَٰٓئِكَةُ كُلُّهُمۡ أَجۡمَعُونَ ٣٠ إِلَّآ إِبۡلِيسَ أَبَىٰٓ أَن يَكُونَ مَعَ ٱلسَّٰجِدِينَ ٣١\nيذكر تعالى نعمته وإحسانه على أبينا آدم -عليه السلام-، وما جرى من عدوه إبليس، وفي ضمن ذلك التحذير لنا من شره وفتنته. السعدي:٤٣١.\nما المقصد من تفصيل قصة خلق آدم وموقف إبليس؟"],[264,"§الحجر\nwords\nفَأَنظِرنِيفَأَمهِلنِي.\nصِرَاطٌطَرِيقٌ.\nسُلطَانٌقُوَّةٌ.\nبِسَلاَمٍسَالِمِينَ مِن كُلِّ سُوءٍ.\nغِلٍّحِقدٍ.\nنَصَبٌتَعَبٌ.\nنَبّىأَخبِر.\ndeeds\nحدد حيلة تحس أن الشيطان غلبك بها ثم فكر في طريقة للتخلص منها.\nسل الله تعالى أن يعصمك من الشيطان، وأن يجعلك من عباده المخلصين.\nسامح أحدًا ظلمك، أو أخطأ عليك؛ فإنه أطهر لقلبك، وفيه راحة نفسك.\nguid\nأحبَّ لغيرك ما تحبُّ لنفسك؛ ففي هذا راحة لقلبك.\nتزيين الملهيات والمحرمات من أقوى أسلحة إبليس.\nإبليس ليس له سلطان وتسلط على أحد؛ إلا من سمح له بذلك.\nrefl\nقَالَ لَمۡ أَكُن لِّأَسۡجُدَ لِبَشَرٍ خَلَقۡتَهُۥ مِن صَلۡصَٰلٖ مِّنۡ حَمَإٖ مَّسۡنُونٖ ٣٣\nيذكر تخلف إبليس عن السجود له من بين سائر الملائكة حسدًا وكفرًا وعنادًا واستكبارًا وافتخارًا بالباطل. ابن كثير:٢/٥٣١.\nإلى أي حدٍ يمكن أن يصل الغرور والحسد بصاحبه؟\nقَالَ رَبِّ فَأَنظِرۡنِيٓ إِلَىٰ يَوۡمِ يُبۡعَثُونَ ٣٦ قَالَ فَإِنَّكَ مِنَ ٱلۡمُنظَرِينَ ٣٧\nوليس إجابة الله لدعائه كرامة في حقه، وإنَّما ذلك امتحان وابتلاء من الله له وللعباد؛ ليتبين الصادق الذي يطيع مولاه دون عدوه ممن ليس كذلك. السعدي:٤٣١.\nما وجه استجابة الله سبحانه لدعاء إبليس؟\nقَالَ رَبِّ بِمَآ أَغۡوَيۡتَنِي لَأُزَيِّنَنَّ لَهُمۡ فِي ٱلۡأَرۡضِ وَلَأُغۡوِيَنَّهُمۡ أَجۡمَعِينَ ٣٩\nوتزيينه هنا يكون بوجهين: إما بفعل المعاصي، وإما بشغلهم بزينة الدنيا عن فعل الطاعة. القرطبي:١٢/٢١٢.\nاذكر بابين يدخل منهما الشيطان على الإنسان؟\nقَالَ رَبِّ بِمَآ أَغۡوَيۡتَنِي لَأُزَيِّنَنَّ لَهُمۡ فِي ٱلۡأَرۡضِ وَلَأُغۡوِيَنَّهُمۡ أَجۡمَعِينَ ٣٩ إِلَّا عِبَادَكَ مِنۡهُمُ ٱلۡمُخۡلَصِينَ ٤٠ قَالَ هَٰذَا صِرَٰطٌ عَلَيَّ مُسۡتَقِيمٌ ٤١\nأي: الذين أخلصتهم واجتبيتهم؛ لإخلاصهم وإيمانهم وتوكلهم. السعدي:٤٣١.\nمن المستثنون من إغواء إبليس؟\nإِنَّ عِبَادِي لَيۡسَ لَكَ عَلَيۡهِمۡ سُلۡطَٰنٌ إِلَّا مَنِ ٱتَّبَعَكَ مِنَ ٱلۡغَاوِينَ ٤٢\nفأهل الإخلاص والإيمان لا سلطان له عليهم؛ ولهذا يهربون من البيت الذي تقرأ فيه سورة البقرة، ويهربون من قراءة آية الكرسي، وآخر سورة البقرة، وغير ذلك من قوارع القرآن. ابن تيمية:٤/١٣١.\nذكرت الآية فئة لا سلطان للشيطان عليهم، فمن هم؟ مع ذكر وسيلتين لطرد الشيطان.\nنَبِّئۡ عِبَادِيٓ أَنِّيٓ أَنَا ٱلۡغَفُورُ ٱلرَّحِيمُ ٤٩\nفإنهم إذا عرفوا كمال رحمته ومغفرته سعوا في الأسباب الموصلة لهم إلى رحمته، وأقلعوا عن الذنوب، وتابوا منها؛ لينالوا مغفرته. السعدي:٤٣٢.\nما موقف المؤمن حين يعلم أن الله غفورٌ رحيم؟\nنَبِّئۡ عِبَادِيٓ أَنِّيٓ أَنَا ٱلۡغَفُورُ ٱلرَّحِيمُ ٤٩ وَأَنَّ عَذَابِي هُوَ ٱلۡعَذَابُ ٱلۡأَلِيمُ ٥٠\nفالعبد ينبغي أن يكون قلبه دائمًا بين الخوف والرجاء، والرغبة والرهبة؛ فإذا نظر إلى رحمة ربه ومغفرته وجوده وإحسانه أحدث له ذلك الرجاء والرغبة، وإذا نظر إلى ذنوبه وتقصيره في حقوق ربه أحدث له الخوف والرهبة، والإقلاع عنها. السعدي:٤٣٢.\nكيف يكون قلب المسلم في هذه الحياة الدنيا؟"],[265,"§الحجر\nwords\nوَجِلُونَفَزِعُونَ، خَائِفُونَ.\nالقَانِطِينَاليَائِسِينَ.\nفَمَا خَطبُكُمفَمَا شَأنُكُمُ الخَطِيرُ؟\nقَدَّرنَاقَضَينَا.\nالغَابِرِينَالبَاقِينَ فِي العَذَابِ.\nوَقَضَينَاأَوحَينَا.\nمَقطُوعٌمُهلَكٌ بِالعَذَابِ.\ndeeds\nابتدئ بالسلام عند دخولك المنزل، أو عند إقبالك على مسلم.\nبشر مسلمًا اليوم بخبر يفرحه ويؤنس قلبه.\nألق كلمة، أو أرسل رسالة؛ تبيّن فيها خطر القنوط من رحمة الله.\nguid\nالبشارة ربما تأتي بعد انقطاع الأسباب الدنيوية.\nاشتغال الإنسان بإصلاح نفسه وأهله ومن حوله ينجيه من المصائب الدنيوية والأخروية.\nلا قيمة للنسب ولا المصاهرة إذا عدم الإيمان.\nrefl\nإِذۡ دَخَلُواْ عَلَيۡهِ فَقَالُواْ سَلَٰمٗا قَالَ إِنَّا مِنكُمۡ وَجِلُونَ ٥٢\nلأن الضيف طرقوا بيتهم في غير وقت طروق الضيف؛ فظنّهم يريدون به شرًا. ابن عاشور:١٤/٥٨.\nلماذا ابتدأ إبراهيم -عليه السلام- بقوله: ﴿إِنَّا مِنكُمۡ وَجِلُونَ﴾؟\nقَالُواْ بَشَّرۡنَٰكَ بِٱلۡحَقِّ فَلَا تَكُن مِّنَ ٱلۡقَٰنِطِينَ ٥٥\nولما كان إبراهيم -عليه السلام- منزّهًا عن القنوط من رحمة الله، جاءوا في موعظته بطريقة الأدب المناسب؛ فنهوه عن أن يكون من زمرة القانطين؛ تحذيرًا له مما يدخله في تلك الزمرة. ابن عاشور:١٤/٦٠.\nفي خطاب الملائكة لإبراهيم -عليه السلام- أنموذج من الأدب، بينه.\nقَالَ وَمَن يَقۡنَطُ مِن رَّحۡمَةِ رَبِّهِۦٓ إِلَّا ٱلضَّآلُّونَ ٥٦\nأي: من ييأس من رحمة ربه ﴿إِلَّا ٱلضَّآلُّونَ﴾ أي: الخاسرون، والقنوط من رحمة الله كبيرة كالأمن من مكره. البغوي:٢/٥٩٠.\nيقنط بعض المذنبين وبعض أهل المصائب من رحمة الله تعالى، فيقول: \"لا يغفر الله لي\"، أو: \"لن تنكشف كربتي\"؛ فكيف تجيب عليه؟\nفَأَسۡرِ بِأَهۡلِكَ بِقِطۡعٖ مِّنَ ٱلَّيۡلِ وَٱتَّبِعۡ أَدۡبَٰرَهُمۡ وَلَا يَلۡتَفِتۡ مِنكُمۡ أَحَدٞ\nوقد جرت عادة الكبراء أن يكونوا أدنى جماعتهم إلى الأمر المخوف؛ سماحًا بأنفسهم، وتثبيتًا لغيرهم، وعلمًا منهم بأن مداناة ما فيه وَجَل لا يُقرِّبُ من أَجَل، وضده لا يُغنِي من قَدَر، ولا يُباعد من ضرر، ولئلَّا يشتغل قلبك بمن خلفك، وليحتشموك؛ فلا يلتفتوا، أو يتخلف أحد منهم، وغير ذلك من المصالح. البقاعي:٤/٢٢٩.\nما المصلحة في أن يمشي لوط -عليه السلام- خلف أهله وهم أمامه عند خروجهم من قريتهم؟\nفَأَسۡرِ بِأَهۡلِكَ بِقِطۡعٖ مِّنَ ٱلَّيۡلِ وَٱتَّبِعۡ أَدۡبَٰرَهُمۡ\nوأن يكون لوط -عليه السلام- يمشي وراءهم ليكون أحفظ لهم، وهكذا كان رسول الله يمشي في الغزو؛ إنَّما يكون ساقةً؛ يزجي الضعيف، ويحمل المنقطع. ابن كثير:٢/٥٣٥.\nتحدث عن سنة النبي في السير إلى الجهاد.\nوَلَا يَلۡتَفِتۡ مِنكُمۡ أَحَدٞ\nلأن الملتفت غير ثابت؛ لأنه إما غير مستيقن لخبرنا، أو متوجع لهم، فمن التفت ناله العذاب، وذلك أيضًا أجدُّ في الهجرة، وأسرع في السير، وأدل على إخراج ما خلَفوه من منازلهم وأمتعتهم من قلوبهم، وعلى أنهم لا يرقُّون لمن غضب الله عليهم مع أنهم ربما رأوا ما لا تطيقه أنفسهم. البقاعي:٤/٢٢٩.\nما الحكمة في أمر آل لوط -عليه السلام- بعدم الالتفات حينما خرجوا من القرية؟\nوَٱتَّقُواْ ٱللَّهَ وَلَا تُخۡزُونِ ٦٩\nوقد ذكرهم بالوازع الديني -وإن كانوا كفارًا- استقصاء للدعوة التي جاء بها، وبالوازع العرفي؛ فقال: ﴿وَٱتَّقُواْ ٱللَّهَ وَلَا تُخۡزُونِ﴾. ابن عاشور:١٤/٦٦.\nجمع لوط -عليه السلام- بين تذكير قومه بالوازع الديني والوازع العرفي، وضح ذلك."],[266,"§الحجر\nwords\nلَعَمرُكَقَسَمٌ مِنَ اللهِ بِحَيَاةِ نَبِيِّنَا مُحَمَّدٍ -صلّى الله عليه وسلّم-.\nسَكرَتِهِمغَفلَتِهِم.\nيَعمَهُونَيَتَرَدَّدُونَ مُتَحَيِّرِينَ.\nلِلمُتَوَسِّمِينَلِلنَّاظِرِينَ، المُعتَبِرِينَ.\nالمُقتَسِمِينَالذين قَسَّمُوا القُرآنَ فَآمَنُوا بِبَعضٍ، وَكَفَرُوا بِبَعضٍ.\ndeeds\nسل الله تعالى أن يرزقك الفراسة، وابذل أسبابها؛ وهي: تقوى الله، ومخالفة هوى النفس.\nاقرأ سورة الفاتحة متدبرًا لها، واستخرج من كل آية فائدة.\nعامل إخوانك المسلمين -خاصة الخدم والعمال- بلطف وبشاشة.\nguid\nالمبالغة في حب زينة الدنيا قد تفقد الإنسان عقله.\nمن أحبه الله شَغَلَهُ بالباقيات الصالحات عن زينة الدنيا.\nقوة البناء والصناعة لا تُغني شيئًا إذا وقع غضب الله.\nrefl\nإِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّلۡمُتَوَسِّمِينَ ٧٥\nوذلك يكون بجودة القريحة، وحدة الخاطر، وصفاء الفكر... وتفريغ القلب من حشو الدنيا، وتطهيره من أدناس المعاصي، وكدورة الأخلاق، وفضول الدنيا. القرطبي:١٢/٢٣٤.\nكيف يصل العبد للتوسم والفراسة الصادقة؟\nوَلَقَدۡ كَذَّبَ أَصۡحَٰبُ ٱلۡحِجۡرِ ٱلۡمُرۡسَلِينَ ٨٠\nكذبوا صالحًا نبيهم -عليه السلام- ومن كذب برسول فقد كذب بجميع المرسلين؛ ولهذا أطلق عليهم تكذيب المرسلين. ابن كثير:٢/٥٣٦.\nكيف كذب أصحاب الحجر جميع المرسلين مع أنهم لم يكذبوا إلا صالحًا؟\nفَمَآ أَغۡنَىٰ عَنۡهُم مَّا كَانُواْ يَكۡسِبُونَ ٨٤\nمن الأموال، والحصون في الجبال، ولا ما أعطوه من القوة. القرطبي:١٢/٢٤٩.\nهل يدفع الغنى أو القوة المادية العذاب عن العبد أو عن الدول؟\nفَٱصۡفَحِ ٱلصَّفۡحَ ٱلۡجَمِيلَ ٨٥\nدون الصفح الذي ليس بجميل؛ وهو الصفح في غير محله، فلا يصفح حيث اقتضى المقام العقوبة؛ كعقوبة المعتدين الظالمين الذين لا ينفع فيهم إلا العقوبة. السعدي:٤٣٤.\nهل هناك صفحٌ غير جميل؟ وما هو؟\nوَلَقَدۡ ءَاتَيۡنَٰكَ سَبۡعٗا مِّنَ ٱلۡمَثَانِي وَٱلۡقُرۡءَانَ ٱلۡعَظِيمَ ٨٧\nعن أبي سعيد بن المعلى قال: قال رسول الله: «﴿ٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ﴾ هي السبع المثاني، والقرآن العظيم الذي أوتيته». الألوسي:١٤/٤٣٢.\nما السبع المثاني المذكورة في الآية؟\nلَا تَمُدَّنَّ عَيۡنَيۡكَ إِلَىٰ مَا مَتَّعۡنَا بِهِۦٓ أَزۡوَٰجٗا مِّنۡهُمۡ وَلَا تَحۡزَنۡ عَلَيۡهِمۡ وَٱخۡفِضۡ جَنَاحَكَ لِلۡمُؤۡمِنِينَ ٨٨\n﴿لَا تَمُدَّنَّ عَيۡنَيۡكَ﴾ أي: لا تنظر إلى ما متعناهم به في الدنيا؛ كأنه يقول: قد آتيناك السبع المثاني، والقرآن العظيم؛ فلا تنظر إلى الدنيا؛ فإن الذي أعطيناك أعظم منها. ابن جزي:١/٤٥٥.\nفي هذه الآية منهج في تزكية النفس تضمّن عدة وصايا، بيّنها.\nوَٱخۡفِضۡ جَنَاحَكَ لِلۡمُؤۡمِنِينَ ٨٨\nأي: ألِن جانبك لمن آمن بك، وتواضع لهم؛ وأصله أن الطائر إذا ضم فرخه إلى نفسه بسط جناحه ثم قبضه على الفرخ، فجعل ذلك وصفًا لتقريب الإنسان أتباعه. القرطبي:١٢/٢٥٤.\nكيف تكون علاقة المؤمن مع إخوانه المؤمنين؟"],[267,"§الحجر ، النحل\nwords\nعِضِينَأَجزَاءً، فَقَالَ بَعضُهُم: سِحرٌ، وَقَالَ بَعضُهُم: كِهَانَةٌ، وَغَيرَ ذَلِكَ.\nفَاصدَعفَاجهَر.\nبِالرُّوحِبِالوَحيِ.\nخَصِيمٌشَدِيدُ الخُصُومَةِ.\nتُرِيحُونَ تَرُدُّونَهَا إِلَى مَبَارِكِهَا وَحَظَائِرِهَا فِي المَسَاءِ.\nتَسرَحُونَتُخرِجُونَهَا لِلمَرعَى فِي الصَّبَاحِ.\ndeeds\nتشارك مع بعض زملائك أو أحد أقاربك في أمر بمعروف أو نهي عن منكر.\nاجمع النعم الواردة في سورة النحل، ثم تأمل فيها حتى تدرك مقصد هذه السورة؛ وهو تعداد النعم.\nاقرأ عن أشراط الساعة الصغرى والكبرى.\nguid\nأهمية الجهر بالحق وبيانه لا سيما إذا لم يكن هناك اضطهاد أو مفاسد تزيد على مصلحة قول الحق.\nالتسبيح والسجود يشرحان الصدر، ويزيلان الضيق والكَدَر عن النفس.\nالعبادة مستمرة حتى يأتي الأجل.\nrefl\nفَوَرَبِّكَ لَنَسۡـَٔلَنَّهُمۡ أَجۡمَعِينَ ٩٢ عَمَّا كَانُواْ يَعۡمَلُونَ ٩٣\nقال ابن عباس -رضي الله عنهما-: \"لا يسألهم سؤال استخبار واستعلام: هل عملتم كذا وكذا؟ لأن الله عالم بكل شيء، ولكن يسألهم سؤال تقريع وتوبيخ\". القرطبي:١٢/٢٦٠.\nما نوع سؤال الله للكافرين عن أعمالهم يوم القيامة؟\nإِنَّا كَفَيۡنَٰكَ ٱلۡمُسۡتَهۡزِءِينَ ٩٥\nوهذا وعد من الله لرسوله أن لا يضره المستهزئون، وأن يكفيه الله إياهم بما شاء من أنواع العقوبة، وقد فعل تعالى؛ فإنه ما تظاهر أحد بالاستهزاء برسول الله وبما جاء به إلا أهلكه الله، وقتله شر قتلة. السعدي:٤٣٥.\nلقد وعد الله رسوله أن يكفيه المستهزئين، فكيف يتحقق هذا الوعد؟ وما حكم من استهزأ بالرسول -صلى الله عليه وسلم-؟\nإِنَّا كَفَيۡنَٰكَ ٱلۡمُسۡتَهۡزِءِينَ ٩٥ ٱلَّذِينَ يَجۡعَلُونَ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَۚ فَسَوۡفَ يَعۡلَمُونَ ٩٦\nوفي وصفهم بذلك [أي: بالشرك] تسلية لرسول الله، وتهوين للخطب عليه -عليه الصلاة والسلام- بالإشارة إلى أنهم لم يقتصروا على الاستهزاء به، بل اجترأوا على العظيمة؛ التي هي الإشراك به سبحانه. الألوسي:١٤/٤٤١.\nفي وصفهم بالشرك بعد بيان كفاية الله تعالى لنبيه مِن شرهم وأذاهم فائدة؛ فما هي؟\nوَٱعۡبُدۡ رَبَّكَ حَتَّىٰ يَأۡتِيَكَ ٱلۡيَقِينُ ٩٩\nكان عمر بن عبد العزيز يقول: \"ما رأيت يقينًا أشبه بالشك من يقين الناس بالموت، ثم لا يستعدون له\"؛ يعني كأنهم فيه شاكون. القرطبي:١٢/٢٦٥.\nماذا يفيد المؤمن من تسمية الله تعالى للموت باليقين في هذه الآية؟\nأَتَىٰٓ أَمۡرُ ٱللَّهِ\nيخبر تعالى عن اقتراب الساعة ودنوها، مُعَبِّرًا بصيغة الماضي الدال على التحقيق والوقوع لا محالة. ابن كثير:٢/٥٤١.\nلماذا قال الله سبحانه: ﴿أَتَىٰٓ أَمۡرُ ٱللَّهِ﴾ بصيغة الماضي، ولم يقل: \"سيأتي أمر الله\"؟ وماذا يفيد المؤمن من ذلك ؟\nيُنَزِّلُ ٱلۡمَلَٰٓئِكَةَ بِٱلرُّوحِ مِنۡ أَمۡرِهِۦ عَلَىٰ مَن يَشَآءُ مِنۡ عِبَادِهِۦٓ\nسماه روحًا؛ لأنه يحيي به القلوب. البغوي:٢/٦٠٤.\nلم سمى الله تعالى الوحي روحًا؟\nوَٱلۡأَنۡعَٰمَ خَلَقَهَاۖ لَكُمۡ فِيهَا دِفۡءٞ وَمَنَٰفِعُ وَمِنۡهَا تَأۡكُلُونَ ٥ وَلَكُمۡ فِيهَا جَمَالٌ حِينَ تُرِيحُونَ وَحِينَ تَسۡرَحُونَ ٦\nهذه السورة تسمى (سورة النعم)؛ فإن الله ذكر في أولها أصول النعم وقواعدها، وفي آخرها متمماتها ومكملاتها. السعدي:٤٣٥-٤٣٦.\nتُسَمَّى سورة النحل بسورة النعم، فما سبب هذه التسمية؟"],[268,"§النحل\nwords\nأَثقَالَكُمأَمتِعَتَكُم الثَّقِيلَةَ.\nجَائِرٌمَائِلٌ عَنِ الحَقِّ.\nفِيهِ تُسِيمُونَفِي الشَّجَرِ تَرعَونَ دَوَابَّكُم.\nذَرَأَخَلَقَ.\nمَوَاخِرَ فِيهِالسُّفُنُ الجَوَارِيَ فِيهِ تَشُقُّ وَجهَ المَاءِ.\ndeeds\nعدد ثلاثًا من نعم الله علينا بالمراكب، ثم اشكر الله تعالى على ذلك.\nإذا ركبت الدابة قل: \"بسم الله، الحمد لله، سبحان الذي سخر لنا هذا، وما كنا له مقرنين، وإنا إلى ربنا لمنقلبون\".\nتفكّر فيما ينبت من ثمار مختلفة، والجميع يسقى بماء واحد، ثم اشكر الله على نعمه.\nguid\nمن أجلِّ نعم الله تعالى على العباد: إنزال الماء من السماء؛ فبه حياة كل شيء.\nالنجوم لا تملك أمر نفسها، فمن باب أولى أنها لا تضر ولا تنفع غيرها، فإليه سبحانه يتجه الدعاء.\nكن عبدًا شكورًا؛ كلما مرت بك نعمة شكرت الله عليها.\nrefl\nوَٱلۡخَيۡلَ وَٱلۡبِغَالَ وَٱلۡحَمِيرَ لِتَرۡكَبُوهَا وَزِينَةٗۚ\nأي: تارة تستعملونها للضرورة في الركوب، وتارة لأجل الجمال والزينة، ولم يذكر الأكل؛ لأن البغال والحمر محرم أكلها، والخيل لا تستعمل في الغالب للأكل. السعدي:٤٣٦.\nلماذا لم يذكر الأكل من منافع هذه الأشياء المذكورة؟\nوَٱلۡخَيۡلَ وَٱلۡبِغَالَ وَٱلۡحَمِيرَ لِتَرۡكَبُوهَا وَزِينَةٗۚ وَيَخۡلُقُ مَا لَا تَعۡلَمُونَ ٨\n﴿وَيَخۡلُقُ مَا لَا تَعۡلَمُونَ﴾: مما يكون بعد نزول القرآن من الأشياء التي يركبها الخلق في البر والبحر والجو، ويستعملونها في منافعهم ومصالحهم؛ فإنه لم يذكرها بأعيانها لأن الله تعالى لا يذكر في كتابه إلا ما يعرفه العباد، أو يعرفون نظيره. وأما ما ليس له نظير فإنه لو ذُكر لم يعرفوه، ولم يفهموا المراد منه؛ فيذكر أصلًا جامعًا يدخل فيه ما يعلمون وما لا يعلمون؛ كما ذكر نعيم الجنة: سمى منه ما نعلم ونشاهد نظيره؛ كالنخل، والأعناب، والرمان، وأَجْمَلَ ما لا نعرف له نظيرًا. السعدي:٤٣٦.\nما طريقة القرآن في ذكر النعم الغيبية من خلال الآية؟\nوَٱلۡخَيۡلَ وَٱلۡبِغَالَ وَٱلۡحَمِيرَ لِتَرۡكَبُوهَا وَزِينَةٗۚ وَيَخۡلُقُ مَا لَا تَعۡلَمُونَ ٨ وَعَلَى ٱللَّهِ قَصۡدُ ٱلسَّبِيلِ وَمِنۡهَا جَآئِرٞۚ وَلَوۡ شَآءَ لَهَدَىٰكُمۡ أَجۡمَعِينَ ٩\nلَمَّا ذكر تعالى من الحيوانات ما يُسار عليه في السبل الحسية، نَبَّه على الطرق المعنوية الدينية. وكثيرًا ما يقع في القرآن العبور من الأمور الحسية إلى الأمور النافعة الدينية. ابن كثير:٢/٥٤٤.\nما علاقة الآيتين المذكورتين بعضهما ببعض؟\nوَعَلَى ٱللَّهِ قَصۡدُ ٱلسَّبِيلِ وَمِنۡهَا جَآئِرٞۚ وَلَوۡ شَآءَ لَهَدَىٰكُمۡ أَجۡمَعِينَ ٩\nلما ذكرت نعمة تيسير السبيل الموصلة إلى المقاصد الجثمانية ارتُقِي إلى التذكير بسبيل الوصول إلى المقاصد الرُّوحانية؛ وهو سبيل الهدى، فكان تعهّد الله بهذه السبيل نعمة أعظمَ من تيسير المسالك الجثمانية؛ لأن سبيل الهدى تحصل به السعادة الأبدية. ابن عاشور:١٤/١١٢.\nأيهما أعظم النعم الحسية، أو الروحية؟ ولماذا؟\nوَعَلَى ٱللَّهِ قَصۡدُ ٱلسَّبِيلِ وَمِنۡهَا جَآئِرٞۚ وَلَوۡ شَآءَ لَهَدَىٰكُمۡ أَجۡمَعِينَ ٩\n﴿وَعَلَى ٱللَّهِ قَصۡدُ ٱلسَّبِيلِ﴾ أي: على الله تقويم طريق الهدى بنصب الأدلة، وبعث الرسل. ابن جزي:١/٤٥٩.\nفي هذه الآية مظهر من مظاهر رحمة الله، وضحه.\nوَهُوَ ٱلَّذِي سَخَّرَ ٱلۡبَحۡرَ لِتَأۡكُلُواْ مِنۡهُ لَحۡمٗا طَرِيّٗا وَتَسۡتَخۡرِجُواْ مِنۡهُ حِلۡيَةٗ تَلۡبَسُونَهَاۖ\nتسخير البحر هو: تمكين البشر من التصرف فيه، وتذليله بالركوب والإرفاء وغيره، وهذه نعمة من نعم الله علينا؛ فلو شاء سلطه علينا وأغرقنا. القرطبي:١٢/٢٩٤.\nبيّن نعمة الله تعالى لعباده بتسخير البحر.\nوَتَرَى ٱلۡفُلۡكَ مَوَاخِرَ فِيهِ وَلِتَبۡتَغُواْ مِن فَضۡلِهِۦ\n﴿وَتَرَى ٱلۡفُلۡكَ مَوَاخِرَ فِيهِ﴾: قال قتادة: \"مقبلة ومدبرة\"؛ وهو أنك ترى سفينتين: إحداهما تقبل والأخرى تدبر، تجريان بريح واحدة. البغوي:٢/٦٠٨.\nبيّن عظيم نعمة الله وقدرته في تسخير الفلك."],[269,"§النحل\nwords\nرَوَاسِيَجِبَالًا ثَوَابِتَ.\nأن تَمِيدَلِئَلاَّ تَمِيلَ وَتَضطَرِبَ.\nأَيَّانَوَقتَ.\nلا جَرَمَحَقًّا.\nأَسَاطِيرُقِصَصُ، وَأَبَاطِيلُ.\nأَوزَارَهُمآثَامَهُم.\nفَخَرَّفَسَقَطَ.\ndeeds\nأرسل رسالة تبين فيها أن من يُدعَون من دون الله تعالى لا يملكون لأنفسهم ضرًّا ولا نفعًا، فضلًا عن أن يملكوه لغيرهم.\nاستعذ بالله من الكبر والاستكبار.\nاستغفر الله من كل رسالةٍ أو خبرٍ أو قصةٍ نشرتها فيها إثم؛ فإنك تحمل وزرها ووزر من عمل بها إلى يوم القيامة.\nguid\nلن تستطيع شكر جميع النعم؛ ولكن كن من عباد الله الشكورين؛ أي المكثرين للشكر.\nاحذر من أن تحمل أوزار غيرك يوم القيامة؛ وذلك بأن تدل غيرك على معصية أو تذكره بها.\nلا يحيق المكر السيئ إلا بأهله.\nrefl\nوَأَلۡقَىٰ فِي ٱلۡأَرۡضِ رَوَٰسِيَ أَن تَمِيدَ بِكُمۡ وَأَنۡهَٰرٗا وَسُبُلٗا لَّعَلَّكُمۡ تَهۡتَدُونَ ١٥\nوفي هذه الآية أدل دليل على استعمال الأسباب. القرطبي:١٢/٣٠٥.\nهل التوكل على الله ينافي الأخذ بالأسباب؟ وضح ذلك.\nوَإِن تَعُدُّواْ نِعۡمَةَ ٱللَّهِ لَا تُحۡصُوهَآۗ إِنَّ ٱللَّهَ لَغَفُورٞ رَّحِيمٞ ١٨\n﴿وَإِن تَعُدُّواْ نِعۡمَةَ ٱللَّهِ﴾ عددًا مجرَّدًا عن الشكر ﴿لَا تُحۡصُوهَآۗ﴾، فضلًا عن كونكم تشكرونها؛ فإن نعمه الظاهرة والباطنة على العباد بعدد الأنفاس واللحظات، من جميع أصناف النعم مما يعرف العباد ومما لا يعرفون، وما يدفع عنهم من النقم فأكثر من أن تحصى. ﴿إِنَّ ٱللَّهَ لَغَفُورٌ رَّحِيمٌ﴾ يرضى منكم باليسير من الشكر مع إنعامه الكثير. السعدي:٤٣٧.\nلماذا ختمت الآية بصفتي (الغفور) و(الرحيم)؟\nوَإِن تَعُدُّواْ نِعۡمَةَ ٱللَّهِ لَا تُحۡصُوهَآۗ إِنَّ ٱللَّهَ لَغَفُورٞ رَّحِيمٞ ١٨\nذكر من أول السورة إلى هنا أنواعًا من مخلوقاته تعالى على وجه الاستدلال بها على وحدانيته؛ ولذلك أعقبها بقوله: ﴿أَفَمَن يَخۡلُقُ كَمَن لَّا يَخۡلُقُۚ﴾، وفيها أيضًا تعداد لنعمه على خلقه؛ ولذلك أعقبها بقوله: ﴿وَإِن تَعُدُّواْ نِعۡمَةَ ٱللَّهِ لَا تُحۡصُوهَآۗ﴾، ثم أعقب ذلك بقوله: ﴿إِنَّ ٱللَّهَ لَغَفُورٌ رَّحِيمٌ﴾ أي: يغفر لكم التقصير في شكر نعمه. ابن جزي: ١/٤٦٠.\nما وجه التعقيب بقوله: ﴿إِنَّ ٱللَّهَ لَغَفُورٌ رَّحِيمٌ﴾؟\nوَٱللَّهُ يَعۡلَمُ مَا تُسِرُّونَ وَمَا تُعۡلِنُونَ ١٩\nيخبر تعالى أنه يعلم الضمائر والسرائر كما يعلم الظواهر، وسيجزي كل عامل بعمله يوم القيامة؛ إن خيرًا فخير، وإن شرًا فشر. ابن كثير:٢/٥٤٦.\nما الفائدة العملية التي تفيدها من معرفة أن الله يعلم ما تسر وما تعلن؟\nوَٱلَّذِينَ يَدۡعُونَ مِن دُونِ ٱللَّهِ لَا يَخۡلُقُونَ شَيۡـٔٗا وَهُمۡ يُخۡلَقُونَ ٢٠ أَمۡوَٰتٌ غَيۡرُ أَحۡيَآءٖۖ وَمَا يَشۡعُرُونَ أَيَّانَ يُبۡعَثُونَ ٢١\nقوله سبحانه: ﴿غَيۡرُ أَحۡيَآءٍۖ﴾... فائدة ذكره... أن بعض ما لا حياة فيه قد تعتريه الحياة؛ كالنطفة، فجيء به للاحتراز عن مثل هذا البعض؛ فكأنه قيل: هم أموات حالًا وغير قابلين للحياة مآلًا. الألوسي: ١٤/٤٨٥.\nما فائدة تأكيد لفظ (أموات) بقوله: ﴿غَيۡرُ أَحۡيَآءٍۖ﴾ في التعبير عن آلهة المشركين؟\nلِيَحۡمِلُوٓاْ أَوۡزَارَهُمۡ كَامِلَةٗ يَوۡمَ ٱلۡقِيَٰمَةِ وَمِنۡ أَوۡزَارِ ٱلَّذِينَ يُضِلُّونَهُم بِغَيۡرِ عِلۡمٍۗ أَلَا سَآءَ مَا يَزِرُونَ ٢٥\nيُضِلُّونَ مَن لا يعلم أنهم ضُلال على الباطل، وفيه تنبيه على أن كيدهم لا يروج على ذي لُبّ؛ وإنَّما يُقلِّدُهُم الجهلة الأغبياء، وفيه زيادة تعيير لهم وذم؛ إذ كان عليهم إرشاد الجاهلين لا إضلالهم... واستدل بالآية على أن المقلِّد يجب عليه أن يبحث ويميز بين المُحِقِّ والمُبطِل، ولا يُعذرُ بالجهل. الألوسي:٤٨٩-٤٩٠.\nمن خلال الآية، تحدث عن مساوئ الجهل والتقليد في أمور الدين.\nوَأَتَىٰهُمُ ٱلۡعَذَابُ مِنۡ حَيۡثُ لَا يَشۡعُرُونَ ٢٦\nأي: من حيث ظنوا أنهم في أمان. القرطبي:١٢/٣١٤.\nهل يأتي العذاب غالبًا من الجهات المأمونة، أم المخوفة؟"],[270,"§النحل\nwords\nيُخزِيهِميَفضَحُهُم، وَيُذِلُّهُم بِالعَذَابِ.\nتُشَاقُّونَ فِيهِمتُحَارِبُونَ، وَتُجَادِلُونَ الأَنبِيَاءَ لأِجلِهِم.\nفَأَلقَوُا السَّلَمَفَاستَسلَمُوا لأَمرِ اللهِ.\nمَثوَىمَقَرُّ.\nيَنظُرُونَيَنتَظِرُونَ.\nوَحَاقَوَأَحَاطَ.\ndeeds\nلا تهجر طلب العلم واحضر اليوم درسًا، أو اسمع محاضرةً، أو اقرأ كتابًا؛ فإن الله تعالى يرفع أهل العلم في الدنيا والآخرة.\nحدد عدة أعمال ثبت أن الله أدخل أصحابها بسببها الجنة، وابدأ اليوم بواحد منها.\nسل الله تعالى حسن الخاتمة.\nguid\nمن تلاعب الشيطان بالعقول الضعيفة أن الالتزام بالوحي يعني التخلف.\nيشهَد العلماء الربانيون يوم القيامة على صنيع أهل الدنيا؛ فعليك بمتابعتهم في الدنيا في معرفة ما يحبه الله ويرضاه.\nاحذر السخـرية أو الاستـهزاء بالدعاة إلى الله والعلماء المصلحين.\nrefl\nقَالَ ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ إِنَّ ٱلۡخِزۡيَ ٱلۡيَوۡمَ وَٱلسُّوٓءَ عَلَى ٱلۡكَٰفِرِينَ ٢٧\nفي هذا فضيلة لأهل العلم، وأنهم الناطقون بالحق في هذه الدنيا ويوم يقوم الأشهاد، وأن لقولهم اعتبارًا عند الله وعند خلقه. السعدي:٤٣٩.\nما فضيلة أهل العلم المذكورة في الآية؟\nٱلَّذِينَ تَتَوَفَّىٰهُمُ ٱلۡمَلَٰٓئِكَةُ ظَالِمِيٓ أَنفُسِهِمۡۖ فَأَلۡقَوُاْ ٱلسَّلَمَ مَا كُنَّا نَعۡمَلُ مِن سُوٓءِۚ بَلَىٰٓۚ إِنَّ ٱللَّهَ عَلِيمُۢ بِمَا كُنتُمۡ تَعۡمَلُونَ ٢٨\nوهذا في بعض مواقف القيامة: ينكرون ما كانوا عليه في الدنيا ظنًا أنه ينفعهم، فإذا شهدت عليهم جوارحهم وتبين ما كانوا عليه أقروا واعترفوا؛ ولهذا لا يدخلون النار حتى يعترفوا بذنوبهم. السعدي:٤٣٩.\nكيف تجمع بين إنكار المشركين لأعمالهم يوم القيامة واعترافهم بها؟\nفَٱدۡخُلُوٓاْ أَبۡوَٰبَ جَهَنَّمَ\nكُلُّ أهل عملٍ يدخلون من الباب اللائق بحالهم. السعدي:٤٣٩.\nأبواب جهنم سبعة، فمن أيِّ باب يدخل أهل النار؟\nفَٱدۡخُلُوٓاْ أَبۡوَٰبَ جَهَنَّمَ خَٰلِدِينَ فِيهَاۖ فَلَبِئۡسَ مَثۡوَى ٱلۡمُتَكَبِّرِينَ ٢٩\nوهم يدخلون جهنم من يوم مماتهم بأرواحهم، وينال أجسادهم في قبورها من حرها وسمومها، فإذا كان يوم القيامة سلكت أرواحهم في أجسادهم وخلدت في نار جهنم. ابن كثير:٢/٥٤٨.\nيمر الكافر بعد مماته بمرحلتين من العذاب، ما هما؟\nوَقِيلَ لِلَّذِينَ ٱتَّقَوۡاْ مَاذَآ أَنزَلَ رَبُّكُمۡۚ قَالُواْ خَيۡرٗاۗ لِّلَّذِينَ أَحۡسَنُواْ فِي هَٰذِهِ ٱلدُّنۡيَا حَسَنَةٞۚ وَلَدَارُ ٱلۡأٓخِرَةِ خَيۡرٞۚ وَلَنِعۡمَ دَارُ ٱلۡمُتَّقِينَ ٣٠\nوحسنة الدّنيا هي الحياة الطيّبة وما فتح الله لهم من زهرة الدنيا مع نعمة الإيمان. ابن عاشور:١٤/١٤٢.\nما حسنة الدنيا الواردة في الآية الكريمة؟\nجَنَّٰتُ عَدۡنٖ يَدۡخُلُونَهَا تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۖ لَهُمۡ فِيهَا مَا يَشَآءُونَۚ كَذَٰلِكَ يَجۡزِي ٱللَّهُ ٱلۡمُتَّقِينَ ٣١\nوذكر بعضهم أن تقديم (فيها) للحصر، و (ما) للعموم بقرينة المقام؛ فيُفيدُ أن الإنسان لا يجد جميع ما يريده إلا في الجنة؛ فتأمَّلهُ. الألوسي:١٤/٥٠٠.\nكيف ينظر المؤمن إلى ما فاته من نعيم الدنيا وكمال زينتها؟\nٱلَّذِينَ تَتَوَفَّىٰهُمُ ٱلۡمَلَٰٓئِكَةُ طَيِّبِينَ\nطابت قلوبهم بمعرفة الله ومحبته، وألسنتهم بذكره والثناء عليه، وجوارحهم بطاعته والإقبال عليه. السعدي:٤٣٩.\nكيف تجعل نفسك طَيِّبَةً عند الموت؟"],[271,"§النحل\nwords\nالطَّاغُوتَمَا يُعبَدُ مِن دُونِ اللهِ.\nجَهدَ أَيمَانِهِممُجتَهِدِينَ بِالحَلِفِ بِأَغلَظِ الأَيمَانِ.\nلَنُبَوِّئَنَّهُملَنُسكِنَنَّهُم.\nحَسَنَةًدَارًا طَيِّبَةً.\ndeeds\nبلّغ أصدقاءك أو إخوانك مسألة نافعة اقتداء بالأنبياء، وسيرًا على نهجهم.\nحدد ثلاثةً من أسباب إهلاك الله للمكذِّبين.\nالهداية لا تكون إلا بعد مشيئة الله وإرادته، فاسأل الله هدايتك.\nguid\nاهتم كثيرًا بتوحيد الله سبحانه في تعلمِك، وتعليمِك، ودعوتك.\nتأمل في أحوال الأمم السابقة إذا مررت بديارهم، أو قرأت شيئًا عنهم؛ فإن ذلك معين على ثبوت التوحيد واستقراره في قلبك.\nاصبر في عبادتك، وتوكل على الله -سبحانه وتعالى- في جميع أمورك؛ فإن ذلك سببٌ للفلاح.\nrefl\nوَلَقَدۡ بَعَثۡنَا فِي كُلِّ أُمَّةٖ رَّسُولًا أَنِ ٱعۡبُدُواْ ٱللَّهَ وَٱجۡتَنِبُواْ ٱلطَّٰغُوتَۖ\nلم يزل تعالى يرسل إلى الناس الرسل بذلك منذ حدث الشرك في بني آدم؛ من عهد نوح أول رسول إلى أهل الأرض إلى زمن خاتم النبيين -صلوات الله عليه وعليهم-، ودعوة الكل واحدة؛ كما قال تعالى: ﴿بوَمَآ أَرۡسَلۡنَا مِن قَبۡلِكَ مِن رَّسُولٍ إِلَّا نُوحِيٓ إِلَيۡهِ أَنَّهُۥ لَآ إِلَٰهَ إِلَّآ أَنَا۠ فَٱعۡبُدُونِ﴾ [الأنبياء: ٢٥]، وكما أخبر هنا في هذه الآية؛ فكيف يسوغ لأحد من المشركين بعد هذا أن يقول: ﴿لَوۡ شَآءَ ٱللَّهُ مَا عَبَدۡنَا مِن دُونِهِۦ مِن شَيۡءٍ﴾؟! القاسمي: ٤/٥١٦.\nماذا نفيد من تعاقب الرسل من نوح إلى زمن النبي على أمر واحد؟\nوَأَقۡسَمُواْ بِٱللَّهِ جَهۡدَ أَيۡمَٰنِهِمۡ لَا يَبۡعَثُ ٱللَّهُ مَن يَمُوتُۚ بَلَىٰ وَعۡدًا عَلَيۡهِ حَقّٗا وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ ٣٨\nووجه التعجيب أنهم يُظهرون تعظيم الله فيقسمون به، ثم يعجزونه عن بعث الأموات. القرطبي: ١٢/٣٢٤.\nما وجه العجب من قسم المكذبين في الآية؟\nوَلِيَعۡلَمَ ٱلَّذِينَ كَفَرُوٓاْ أَنَّهُمۡ كَانُواْ كَٰذِبِينَ ٣٩\nحين يرون أعمالهم حسراتٍ عليهم، وما نفعتهم آلهتهم التي يدعون مع الله من شيء لمَّا جاء أمر ربك، وحين يرون ما يعبدون حطبًا لجهنم، وتكور الشمس والقمر، وتتناثر النجوم، ويتضح لمن يعبدها أنها عبيد مسخرات، وأنهن مفتقرات إلى الله في جميع الحالات. السعدي: ٤٤٠.\nكيف يعلم الذين كفروا يوم القيامة أن زعماءهم كانوا كاذبين؟\nوَٱلَّذِينَ هَاجَرُواْ فِي ٱللَّهِ مِنۢ بَعۡدِ مَا ظُلِمُواْ لَنُبَوِّئَنَّهُمۡ فِي ٱلدُّنۡيَا حَسَنَةٗۖ وَلَأَجۡرُ ٱلۡأٓخِرَةِ أَكۡبَرُۚ لَوۡ كَانُواْ يَعۡلَمُونَ ٤١\nويحتمل أن يكون سبب نزول هذه الآية الكريمة في مهاجرة الحبشة... تركوا مساكنهم وأموالهم؛ فعوضهم الله خيرا منها في الدنيا؛ فإن من ترك شيئًا لله عوضه الله بما هو خير له منه، وكذلك وقع... ﴿لَوۡ كَانُواْ يَعۡلَمُونَ﴾ أي: لو كان المتخلفون عن الهجرة معهم يعلمون ما ادَّخر الله لمن أطاعه واتبع رسوله. ابن كثير: ٢/٥٥١.\nمن ترك شيئًا لله عوضه الله خيرًا منه، تحدث عن ذلك في ضوء هذه الآية.\nوَٱلَّذِينَ هَاجَرُواْ فِي ٱللَّهِ مِنۢ بَعۡدِ مَا ظُلِمُواْ لَنُبَوِّئَنَّهُمۡ فِي ٱلدُّنۡيَا حَسَنَةٗۖ وَلَأَجۡرُ ٱلۡأٓخِرَةِ أَكۡبَرُۚ لَوۡ كَانُواْ يَعۡلَمُونَ ٤١\nقال قتادة: \"هم أصحاب النبي -صلى الله عليه وسلم- ظلمهم أهل مكة، وأخرجوهم من ديارهم، حتى لحق طائفة منهم بالحبشة، ثم بوأهم الله المدينة بعد ذلك؛ فجعلها لهم دار هجرة، وجعل لهم أنصارًا من المؤمنين\". القرطبي: ٢/٦١٥.\nحينما ترى المعذبين والمظلومين في زماننا؛ فبأي آية من كتاب الله تعزيهم؟\nٱلَّذِينَ صَبَرُواْ وَعَلَىٰ رَبِّهِمۡ يَتَوَكَّلُونَ ٤٢\nوالتعبير في جانب الصبر بالماضي، وفي جانب التوكّل بالمضارع إيماء إلى أن صبرهم قد آذن بالانقضاء؛ لانقضاء أسبابه، وأن الله قد جعل لهم فرجًا بالهجرة الواقعة والهجرة المترقّبة؛ فهذا بشارة لهم. وأنّ التوكّل ديدنهم؛ لأنهم يستقبلون أعمالًا جليلة تتمّ لهم بالتوكّل على الله في أمورهم؛ فهم يكرّرونه، وفي هذا بشارة بضمان النجاح. ابن عاشور: ١٤/١٥٩.\nلماذا جاء التعبير في جانب الصبر بالفعل الماضي وفي جانب التوكل بالفعل المضارع؟\nٱلَّذِينَ صَبَرُواْ وَعَلَىٰ رَبِّهِمۡ يَتَوَكَّلُونَ ٤٢\n﴿وَعَلَىٰ رَبِّهِمۡ يَتَوَكَّلُونَ﴾: في كل أمورهم. وقال بعض أهل التحقيق: خيار الخلق من إذا نابه أمر صبر، وإذا عجز عن أمر توكل؛ قال الله تعالى: ﴿ٱلَّذِينَ صَبَرُواْ وَعَلَىٰ رَبِّهِمۡ يَتَوَكَّلُونَ﴾. القرطبي: ١٢/٣٢٨.\nما أبرز صفات خيار الخلق التي ذكرها الله تعالى؟"],[272,"§النحل\nwords\nوَالزُّبُرِالكُتُبِ السَّمَاوِيَّةِ.\nمَكَرُوا السَّيِّئَاتِدَبَّرُوا المَكَايِدَ.\nيَتَفَيَّأُيَمِيلُ.\nدَاخِرُونَخَاضِعُونَ لِعَظَمَةِ اللهِ.\nوَاصِبًادَائِمًا.\ndeeds\nاقرأ حديثًا، أو مجموعة أحاديث من كتاب التفسير من صحيح البخاري، وتأمل كيف كان رسول الله -صلى الله عليه وسلم- يبين القرآن.\nتعرّف على معنى اسمي الله: (الرؤوف) و(الرحيم)، وادع الله بهما.\nتذكر نعمة عظيمة أنعم الله بها عليك، ثم قل: \"الله أنعم علي بكذا\"، وإياك ونسبتها إلى الخلق أو إلى نفسك.\nguid\nأي مسألة تجهلها فعليك أن ترجع إلى أهل الاختصاص بها، ولا تأتِ بشيء من عندك.\nلن تصل إلى مقاصد القرآن ودقائقه إلا بمعرفة سنة الحبيب -صلى الله عليه وسلم-.\nالمصر على معصية قد ينزل الله به العذاب من حيث لا يشعر ولا يتوقع.\nrefl\nفَسۡـَٔلُوٓاْ أَهۡلَ ٱلذِّكۡرِ إِن كُنتُمۡ لَا تَعۡلَمُونَ ٤٣\nوفي ضِمنِهِ تعديلٌ لأهل العلم، وتزكيةٌ لهم؛ حيث أمر بسؤالهم، وأن بذلك يخرج الجاهل من التبعة، فدلَّ على أن الله ائتمنهم على وحيه وتنزيله. السعدي:٤٤١.\nدلت الآية على فضيلة لأهل العلم، بَيِّنها.\nفَسۡـَٔلُوٓاْ أَهۡلَ ٱلذِّكۡرِ إِن كُنتُمۡ لَا تَعۡلَمُونَ ٤٣ بِٱلۡبَيِّنَٰتِ وَٱلزُّبُرِۗ وَأَنزَلۡنَآ إِلَيۡكَ ٱلذِّكۡرَ\nوأفضل أهل الذكر: أهل القرآن العظيم؛ فإنهم أهل الذكر على الحقيقة، وأولى من غيرهم بهذا الاسم؛ ولهذا قال تعالى: ﴿وَأَنزَلۡنَآ إِلَيۡكَ ٱلذِّكۡرَ﴾ أي: القرآن. السعدي:٤٤١.\nأفضل العلماء أقربهم من القرآن، بين هذا من خلال الآية.\nأَوۡ يَأۡخُذَهُمۡ عَلَىٰ تَخَوُّفٖ فَإِنَّ رَبَّكُمۡ لَرَءُوفٞ رَّحِيمٌ ٤٧\n﴿أَوۡ يَأۡخُذَهُمۡ عَلَىٰ تَخَوُّفٍ﴾: فيه وجهان؛ أحدهما: أن معناه على تنقص؛ أي ينتقص أموالهم وأنفسهم شيئًا بعد شيء، حتى يهلكوا من غير أن يهلكهم جملة واحدة، ولهذا أشار بقوله: ﴿فَإِنَّ رَبَّكُمۡ لَرَءُوفٌ رَّحِيمٌ﴾؛ لأن الأخذ هكذا أخف من غيره، وقد كان عمر بن الخطاب أشكل عليه معنى التخوف في الآية، حتى قال له رجل من هذيل: التخوف: التنقص في لغتنا. والوجه الثاني: أنه من الخوف؛ أي يهلك قومًا قبلهم فيتخوّفوا هم ذلك، فيأخذهم بعد أن توقعوا العذاب وخافوه. ابن جزي: ١/٤٦٥.\nما المقصود بأخذهم على تخَوُّف؟\nأَفَأَمِنَ ٱلَّذِينَ مَكَرُواْ ٱلسَّيِّـَٔاتِ أَن يَخۡسِفَ ٱللَّهُ بِهِمُ ٱلۡأَرۡضَ أَوۡ يَأۡتِيَهُمُ ٱلۡعَذَابُ مِنۡ حَيۡثُ لَا يَشۡعُرُونَ ٤٥ أَوۡ يَأۡخُذَهُمۡ فِي تَقَلُّبِهِمۡ فَمَا هُم بِمُعۡجِزِينَ ٤٦ أَوۡ يَأۡخُذَهُمۡ عَلَىٰ تَخَوُّفٖ فَإِنَّ رَبَّكُمۡ لَرَءُوفٞ رَّحِيمٌ ٤٧\nولكنه رؤوف رحيم؛ لا يعاجل العاصين بالعقوبة، بل يمهلهم ويعافيهم ويرزقهم، وهم يؤذونه ويؤذون أولياءه، ومع هذا يفتح لهم أبواب التوبة، ويدعوهم إلى الإقلاع عن السيئات التي تضرهم، ويعدهم بذلك أفضل الكرامات، ومغفرة ما صدر منهم من الذنوب. السعدي:٤٤١.\nلماذا ختمت آيات التهديد هذه بالأسماء الدالة على الرحمة؟\nيَخَافُونَ رَبَّهُم مِّن فَوۡقِهِمۡ وَيَفۡعَلُونَ مَا يُؤۡمَرُونَ۩ ٥٠\nهنا موضع سجود للقارئ بالاتفاق، وحكمته هنا إظهار المؤمن أنه من الفريق الممدوح بأنه مشابه للملائكة في السجود لله تعالى. ابن عاشور:١٤/١٧١.\nما حكمة سجود التلاوة عند الآية الكريمة؟\nوَقَالَ ٱللَّهُ لَا تَتَّخِذُوٓاْ إِلَٰهَيۡنِ ٱثۡنَيۡنِۖ إِنَّمَا هُوَ إِلَٰهٞ وَٰحِدٞ\nوالاقتصار على الأمر بالرّهبة، وقصرها على كونها من الله يفهم منه الأمر بقصر الرغبة عليه؛ لدلالة قصر الرهبة على اعتقاد قصر القدرة التامة عليه تعالى. ابن عاشور:١٤/١٧٤.\nما فائدة الاقتصار على الأمر بالرهبة، وقصرها على كونها من الله تعالى وحده؟\nوَمَا بِكُم مِّن نِّعۡمَةٖ فَمِنَ ٱللَّهِۖ ثُمَّ إِذَا مَسَّكُمُ ٱلضُّرُّ فَإِلَيۡهِ تَجۡـَٔرُونَ ٥٣\nأي: كيف تتقون غير الله، وما بكم من نعمة فمنه وحده، ﴿فَإِلَيۡهِ تَجۡـَٔرُونَ﴾ أي: ترفعون أصواتكم بالاستغاثة والتضرع. ابن جزي:١/٤٦٦.\nكيف تستنبط من هذه الآية أن التوحيد فطرة في الإنسان؟"],[273,"§النحل\nwords\nكَظِيمٌمُمتَلِئٌ غَمًّا وَحُزنًا.\nهُونٍذُلٍّ، وَهَوَانٍ.\nيَدُسُّهُيَدفِنُهُ.\nلا جَرَمَحَقًّا.\nمُفرَطُونَمَترُوكُونَ فِي النَّارِ، مَنسِيُّونَ.\ndeeds\nأرسل رسالة تبين فيها حال المرأة في الجاهلية القديمة والحديثة، وحالها في الإسلام.\nسبح الله بصفتيه: (العزيز) و(الحكيم)، ثم اعلم أن العزة والحكمة لا تنال إلا منه، فاطلبها من مالكها -جل وعلا-.\nسَلِ الله أن يهديك ويرحمك بكتابه.\nguid\nالمؤمن إذا تذكر أنه مسؤول أمام الله تعالى -قوله وفعله- فإنه يحذر من قول السوء وعمله.\nأحسن معاملة بناتك وأخواتك، وأظهر البشر لمقدمهن.\nاحذر أن تكون ممن زين له الشيطان سوء عمله؛ فحسن له القبيح، وقبح له الحسن، وهو غافل.\nrefl\nوَيَجۡعَلُونَ لِمَا لَا يَعۡلَمُونَ نَصِيبٗا مِّمَّا رَزَقۡنَٰهُمۡۗ\nيجعلون لأصنامهم - التي لا تعلم ولا تنفع ولا تضر- نصيبًا مما رزقهم الله، وأنعم به عليهم؛ فاستعانوا برزقه على الشرك به، وتقربوا به إلى أصنام منحوتة. السعدي:٤٤٢.\nبَيِّن مدى حمق المشركين في صرفهم القربات للشركاء من دون الله.\nتَٱللَّهِ لَتُسۡـَٔلُنَّ عَمَّا كُنتُمۡ تَفۡتَرُونَ ٥٦\nفأقسم تعالى بنفسه الكريمة ليسألنهم عن ذلك الذي افتروه وائتفكوه، وليقابلنهم عليه، وليجازينهم أوفر الجزاء في نار جهنم. ابن كثير:٢/٥٥٤.\nما المراد من وراء الإخبار بأنهم سيسألون عما يفترونه؟\nوَإِذَا بُشِّرَ أَحَدُهُم بِٱلۡأُنثَىٰ ظَلَّ وَجۡهُهُۥ مُسۡوَدّٗا وَهُوَ كَظِيمٞ ٥٨ يَتَوَٰرَىٰ مِنَ ٱلۡقَوۡمِ مِن سُوٓءِ مَا بُشِّرَ بِهِۦٓۚ أَيُمۡسِكُهُۥ عَلَىٰ هُونٍ أَمۡ يَدُسُّهُۥ فِي ٱلتُّرَابِۗ أَلَا سَآءَ مَا يَحۡكُمُونَ ٥٩\nوالآية ظاهرة في ذم مَن يحزن إذا بُشِّر بالأنثى؛ حيث أخبرت أن ذلك فعل الكفرة. وقد أخرج ابن جرير وغيره عن قتادة أنه قال في قوله سبحانه: ﴿وَإِذَا بُشِّرَ﴾: \"هذا صنيع مشركي العرب؛ أخبركم الله تعالى بخبثه؛ فأما المؤمن فهو حقيق أن يرضى بما قسم الله تعالى له، وقضاء الله تعالى خير من قضاء المرء لنفسه. ولعمري ما ندري أيٌّ خير؛ لرُبَّ جارية خيرٌ لأهلها من غلام. وإنَّما أخبركم الله -عز وجل- بصنيعهم لتجتنبوه، ولتنتهوا عنه\". الألوسي:١٤/٥٤٩.\nما الواجب على المسلم إذا ولدت زوجته خلاف ما يتمنى؟\nوَلَوۡ يُؤَاخِذُ ٱللَّهُ ٱلنَّاسَ بِظُلۡمِهِم مَّا تَرَكَ عَلَيۡهَا مِن دَآبَّةٖ وَلَٰكِن يُؤَخِّرُهُمۡ إِلَىٰٓ أَجَلٖ مُّسَمّٗىۖ فَإِذَا جَآءَ أَجَلُهُمۡ لَا يَسۡتَٔۡخِرُونَ سَاعَةٗ وَلَا يَسۡتَقۡدِمُونَ ٦١\n﴿وَلَوۡ يُؤَاخِذُ ٱللَّهُ ٱلنَّاسَ بِظُلۡمِهِم﴾ من غير زيادة ولا نقص ﴿مَّا تَرَكَ عَلَيۡهَا مِن دَآبَّةٍ﴾ أي: لأهلك المباشرين للمعصية وغيرهم من أنواع الدواب والحيوانات؛ فإن شؤم المعاصي يهلك به الحرث والنسل. ﴿وَلَٰكِن يُؤَخِّرُهُمۡ﴾ عن تعجيل العقوبة عليهم إلى أجل مسمى؛ وهو يوم القيامة. ﴿فَإِذَا جَآءَ أَجَلُهُمۡ لَا يَسۡتَأۡخِرُونَ سَاعَةً وَلَا يَسۡتَقۡدِمُونَ﴾ فليحذروا ما داموا في وقت الإمهال قبل أن يجيء الوقت الذي لا إمهال فيه. السعدي:٤٤٣.\nضرر المعصية من الفرد يعود على جميع المجتمع، وضح ذلك من خلال الآية٠\nوَلَوۡ يُؤَاخِذُ ٱللَّهُ ٱلنَّاسَ بِظُلۡمِهِم مَّا تَرَكَ عَلَيۡهَا مِن دَآبَّةٖ وَلَٰكِن يُؤَخِّرُهُمۡ إِلَىٰٓ أَجَلٖ مُّسَمّٗىۖ فَإِذَا جَآءَ أَجَلُهُمۡ لَا يَسۡتَٔۡخِرُونَ سَاعَةٗ وَلَا يَسۡتَقۡدِمُونَ ٦١\nروي أن أبا هريرة -رضي الله عنه- سمع رجلًا يقول: إن الظالم لا يضر إلا نفسه، فقال: \"بئس ما قلت؛ إن الحبارى تموت في وكرها بظلم الظالم\". البغوي:٢/٦٢٠.\nإلى أي حد يصل شؤم الظلم وأهله؟\nفَزَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ أَعۡمَٰلَهُمۡ فَهُوَ وَلِيُّهُمُ ٱلۡيَوۡمَ وَلَهُمۡ عَذَابٌ أَلِيمٞ ٦٣\nسماه وليًا لهم لطاعتهم إياه. البغوي:٢/٦٢١.\nما وجه ولاية الشيطان لهم؟\nوَمَآ أَنزَلۡنَا عَلَيۡكَ ٱلۡكِتَٰبَ إِلَّا لِتُبَيِّنَ لَهُمُ ٱلَّذِي ٱخۡتَلَفُواْ فِيهِ وَهُدٗى وَرَحۡمَةٗ لِّقَوۡمٖ يُؤۡمِنُونَ ٦٤\nفالقرآن أهم مقاصده هذه الفوائد الجامعة لأصول الخير؛ وهي: كشف الجهالات، والهدى إلى المعارف الحق، وحصول أثر ذينك الأمرين؛ وهو الرحمة الناشئة عن مجانبة الضلال واتباع الهدى. ابن عاشور:١٤/١٩٦.\nما مقاصد إنزال القرآن الكريم؟"],[274,"§النحل\nwords\nلَعِبرَةًلَعِظَةً.\nفَرثٍمَا فِي الكَرِشِ.\nسَائِغًالَذِيذًا لا يَغَصُّ بِهِ شَارِبُهُ.\nيَعرِشُونَيَبنُونَ مِنَ البُيُوتِ وَالسُّقُوفِ لِلنَّحلِ.\nفَاسلُكِيفَادخُلِي.\nذُلُلًامُذَلَّلَةً، مُسَخَّرَةً.\nأَرذَلِ العُمُرِأَردَأِ أَعمَارِكُم، وَهُوَ الهَرَمُ.\ndeeds\nاشرب لبنًا، ثم تذكر كيف أخرجه الله تعالى لك، ثم قل: \"اللهم بارك لنا فيه، وزدنا منه\".\nاستشف اليوم بشرب العسل؛ ففيه شفاء.\nقل: \"أَعوذ بك من البخلِ والكَسلِ، وأَرذلِ العُمُرِ، وعذاب القَبرِ، وفتنة الدَّجَّالِ، وفتْنةِ المحيا والممات\".\nguid\nلو تأملت كيف تدرج اللبن من برسيم في المزرعة الى مصنع في بطن الحيوان، حتى صار مشروبًا لذيذًا على مائدتك لما وفيت الله حقه من الشكر.\nإياك والحسد؛ فإن الله تعالى هو الذي فاضل بين الناس في أرزاقهم وعقولهم.\nكل طيب حلال، وكل خبيث حرام.\nrefl\nوَإِنَّ لَكُمۡ فِي ٱلۡأَنۡعَٰمِ لَعِبۡرَةٗۖ\nقال أبو بكر الوراق: \"العبرة في الأنعام: تسخيرها لأربابها وطاعتها لهم، وتمردك على ربك وخلافك له في كل شيء. ومن أعظم العبر بريء يحمل مذنبًا\". القرطبي:١٢/٣٥٠.\nبيِّن العبرة والعظة التي جعلها الله تعالى في تسخير الأنعام.\nوَإِنَّ لَكُمۡ فِي ٱلۡأَنۡعَٰمِ لَعِبۡرَةٗۖ نُّسۡقِيكُم مِّمَّا فِي بُطُونِهِۦ مِنۢ بَيۡنِ فَرۡثٖ وَدَمٖ لَّبَنًا خَالِصٗا سَآئِغٗا لِّلشَّٰرِبِينَ ٦٦\nفهل هذه إلا قدرة إلهية لا أمور طبيعية؛ فأي شيءٍ في الطبيعة يقلب العلف الذي تأكله البهيمة والشراب الذي تشربه من الماء العذب والملح لبنًا خالصًا سائغًا للشاربين. السعدي:٤٤٤.\nما وجه العبرة من خروج اللبن من بطون الأنعام؟\nوَمِن ثَمَرَٰتِ ٱلنَّخِيلِ وَٱلۡأَعۡنَٰبِ تَتَّخِذُونَ مِنۡهُ سَكَرٗا وَرِزۡقًا حَسَنًاۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّقَوۡمٖ يَعۡقِلُونَ ٦٧\n﴿إِنَّ فِي ذَٰلِكَ لَأٓيَةً لِّقَوۡمٍ يَعۡقِلُونَ﴾ عن الله كمال اقتداره؛ حيث أخرجها من أشجار شبيهة بالحطب، فصارت ثمرة لذيذة، وفاكهة طيبة. وعلى شمول رحمته؛ حيث عَمَّ بها عباده، ويسَّرها لهم. السعدي:٤٤٤.\nما الآيات التي يفيدها العاقلون من وجود الثمرات المختلفة المتنوعة؟\nوَمِن ثَمَرَٰتِ ٱلنَّخِيلِ وَٱلۡأَعۡنَٰبِ تَتَّخِذُونَ مِنۡهُ سَكَرٗا وَرِزۡقًا حَسَنًاۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّقَوۡمٖ يَعۡقِلُونَ ٦٧\nقال ابن عباس في قوله: ﴿سَكَرًا وَرِزۡقًا حَسَنًاۚ﴾: \"السكر: ما حرم من ثمرتيهما، والرزق الحسن: ما أحل من ثمرتيهما\"... ﴿إِنَّ فِي ذَٰلِكَ لَأٓيَةً لِّقَوۡمٍ يَعۡقِلُونَ﴾: ناسب ذكر العقل هاهنا؛ فإنه أشرف ما في الإنسان؛ ولهذا حرم الله على هذه الأمة الأشربة المسكرة صيانة لعقولها. ابن كثير:٢/٥٥٦.\nما وجه مناسبة ختم الآية بذكر العقل؟\nثُمَّ كُلِي مِن كُلِّ ٱلثَّمَرَٰتِ فَٱسۡلُكِي سُبُلَ رَبِّكِ ذُلُلٗاۚ يَخۡرُجُ مِنۢ بُطُونِهَا شَرَابٞ مُّخۡتَلِفٌ أَلۡوَٰنُهُۥ فِيهِ شِفَآءٞ لِّلنَّاسِۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّقَوۡمٖ يَتَفَكَّرُونَ ٦٩\n﴿إِنَّ فِي ذَٰلِكَ لَأٓيَةً لِّقَوۡمٍ يَتَفَكَّرُونَ﴾ أي: يعتبرون، ومن العبرة في النحل بإنصاف النظر وإلطاف الفكر في عجيب أمرها؛ فيشهد اليقين بأن ملهمها الصنعة اللطيفة مع البنية الضعيفة وحذقها باحتيالها في تفاوت أحوالها هو الله -سبحانه وتعالى-... ثم أنها تأكل الحامض والمر والحلو والمالح والحشائش الضارة؛ فيجعله الله تعالى عسلًا حلوًا وشفاءً، وفي هذا دليل على قدرته. القرطبي:١٢/٣٧٤.\nبيّن وجهًا من أوجه العجب في هذا المخلوق؛ وهو النحل.\nيَخۡرُجُ مِنۢ بُطُونِهَا شَرَابٞ مُّخۡتَلِفٌ أَلۡوَٰنُهُۥ فِيهِ شِفَآءٞ لِّلنَّاسِۚ\nقال بعض من تكلم على الطب النبوي: لو قال \"فيه الشفاء للناس\" لكان دواء لكل داء، ولكن قال: ﴿فِيهِ شِفَآءٌ لِّلنَّاسِۚ﴾؛ أي: يصلح لكل أحد من أدواء باردة؛ فإنه حار، والشيء يداوى بضده. ابن كثير:٢/٥٥٦.\nلم قال سبحانه ﴿فِيهِ شِفَآءٌ﴾ ولم يقل: \"فيه الشفاء\"؟\nوَٱللَّهُ خَلَقَكُمۡ ثُمَّ يَتَوَفَّىٰكُمۡۚ وَمِنكُم مَّن يُرَدُّ إِلَىٰٓ أَرۡذَلِ ٱلۡعُمُرِ لِكَيۡ لَا يَعۡلَمَ بَعۡدَ عِلۡمٖ شَيۡـًٔاۚ إِنَّ ٱللَّهَ عَلِيمٞ قَدِيرٞ ٧٠\nوكان من دعائه عن أنس: «أعوذ بك من البخل، والكسل، وأرذل العمر، وعذاب القبر، وفتنة الدجال، وفتنة المحيا والممات». الألوسي:١٤/٥٧٢.\nكيف كان النبي يتأول هذه الآية: ﴿وَمِنكُم مَّن يُرَدُّ إِلَىٰٓ أَرۡذَلِ ٱلۡعُمُرِ﴾؟"],[275,"§النحل\nwords\nالأَمثَالَالأَشبَاهَ الَّذِينَ تُشرِكُونَهُم مَعَ اللهِ تَعَالَى.\nأَبكَمُأَخرَسُ لا يَتَكَلَّمُ خِلقَةً.\nكَلٌّعِبءٌ، ثَقِيلٌ.\nمَولاهُسَيِّدُهُ الَّذِي يَلِي أُمُورَهُ، وَيَعُولُهُ.\nكَلَمحِ البَصَرِكَخَطفَةٍ بِالبَصَرِ، وَنَظرَةٍ سَرِيعَةٍ.\ndeeds\nاحمد الله أن أسبغ عليك نعمه ورزقه، ثم أنفق مرة سرًّا وأخرى علانيةً.\nتذكر قريبًا أو صديقًا لك مات فجأة، ثم تخيل أن مصيرك مثله.\nتأمل في الطير كيف يطير ويعلو في الهواء؟! فتفكرك هذا استجابة لأمر الله تعالى.\nguid\nمن يتكلم بالعدل ويأمر به فله قيمة عالية عند الله سبحانه.\nتخيل لو تعطلت أو مرضت إحدى نعم السمع والبصر والفؤاد؛ فما حالك؟! اشكر الله سبحانه عليها.\nاستخدم ضرب المثل في نصحك ودعوتك؛ لتقريب الأمور.\nrefl\nفَلَا تَضۡرِبُواْ لِلَّهِ ٱلۡأَمۡثَالَۚ إِنَّ ٱللَّهَ يَعۡلَمُ وَأَنتُمۡ لَا تَعۡلَمُونَ ٧٤\nأي: يعلم قبح ما تشركون وأنتم لا تعلمونه، ولو علمتموه لما جرأتم عليه؛ فهو تعليل للنهي. أو يعلم كنه الأشياء وأنتم لا تعلمونه؛ فدعوا رأيكم وقياسكم دون نصه. القاسمي:٤/٥٣٤.\nما وجه تذييل الآية بقوله: ﴿إِنَّ ٱللَّهَ يَعۡلَمُ وَأَنتُمۡ لَا تَعۡلَمُونَ﴾؟\nفَلَا تَضۡرِبُواْ لِلَّهِ ٱلۡأَمۡثَالَۚ إِنَّ ٱللَّهَ يَعۡلَمُ وَأَنتُمۡ لَا تَعۡلَمُونَ ٧٤\nووجه كون الإشراك ضرب مثل لله أنهم أثبتوا للأصنام صفات الإلهية وشبّهوها بالخالق. ابن عاشور:١٤/ ٢٢٣.\nما وجه الخطأ والجهل في عبادة المشركين للأصنام؟\nضَرَبَ ٱللَّهُ مَثَلًا عَبۡدٗا مَّمۡلُوكٗا لَّا يَقۡدِرُ عَلَىٰ شَيۡءٖ وَمَن رَّزَقۡنَٰهُ مِنَّا رِزۡقًا حَسَنٗا فَهُوَ يُنفِقُ مِنۡهُ سِرّٗا وَجَهۡرًاۖ هَلۡ يَسۡتَوُۥنَۚ ٱلۡحَمۡدُ لِلَّهِۚ بَلۡ أَكۡثَرُهُمۡ لَا يَعۡلَمُونَ ٧٥\nفشبّه حال أصنامهم في العجز عن رزقهم بحال مملوك لا يقدر على تصرّف في نفسه، ولا يملك مالًا. ابن عاشور:١٤/٢٢٣.\nالأصنام والأضرحة والقبور عاجزة عن نفع نفسها، فكيف تنفع غيرها، وضح ذلك من خلال الآية.\nضَرَبَ ٱللَّهُ مَثَلًا عَبۡدٗا مَّمۡلُوكٗا لَّا يَقۡدِرُ عَلَىٰ شَيۡءٖ وَمَن رَّزَقۡنَٰهُ مِنَّا رِزۡقًا حَسَنٗا فَهُوَ يُنفِقُ مِنۡهُ سِرّٗا وَجَهۡرًاۖ هَلۡ يَسۡتَوُۥنَۚ ٱلۡحَمۡدُ لِلَّهِۚ بَلۡ أَكۡثَرُهُمۡ لَا يَعۡلَمُونَ ٧٥\nمثلٌ لله تعالى وللأصنام؛ فالأصنام كالعبد المملوك الذي لا يقدر على شيء، والله تعالى له الملك، وبيده الرزق، ويتصرف فيه كيف يشاء؛ فكيف يُسوّى بينه وبين الأصنام؟! ابن جزي:١/٤٣٢.\nالشرك ينافي العقل، وضح ذلك من خلال الآية.\nوَجَعَلَ لَكُمُ ٱلسَّمۡعَ وَٱلۡأَبۡصَٰرَ وَٱلۡأَفۡـِٔدَةَ\nخص هذه الأعضاء الثلاثة لشرفها وفضلها، ولأنها مفتاح لكل علم؛ فلا يصل للعبد علم إلا من أحد هذه الأبواب الثلاثة. السعدي:٤٤٥.\nلماذا خُصَّت هذه الأعضاء الثلاثة بالذكر؟\nأَلَمۡ يَرَوۡاْ إِلَى ٱلطَّيۡرِ مُسَخَّرَٰتٖ فِي جَوِّ ٱلسَّمَآءِ مَا يُمۡسِكُهُنَّ إِلَّا ٱللَّهُۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يُؤۡمِنُونَ ٧٩\nوجمع الآيات؛ لأن في الطير دلائل مختلفة من: خلقة الهواء وخلقة أجساد الطير مناسبة للطيران في الهواء، وخلق الإلهام للطير بأن يسبح في الجو، وبأن لا يسقط إلى الأرض إلا بإرادته. ابن عاشور:١٤/٢٣٦.\nلماذا وردت لفظة: (لآيات) في الآية بصيغة الجمع؟\nإِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يُؤۡمِنُونَ\nلأنهم المنتفعون بآيات الله، المتفكرون فيما جُعلت آيةً عليه، وأمَّا غيرهم فإن نظرهم نظر لهو وغفلة. السعدي:٤٤٥.\nلماذا خُصَّ المؤمنون بالانتفاع بالآيات الكونية؟"],[276,"§النحل\nwords\nتَستَخِفُّونَهَايَخِفُّ عَلَيكُم حَملُهَا وَهِيَ الخِيَامُ.\nظَعنِكُمتَرحَالِكُم.\nوَأَوبَارِهَاالأَوبَارِ مِنَ الإِبِلِ.\nظِلالًاأَشيَاءَ تَستَظِلُّونَ بِهَا؛ كَالأَشجَارِ.\nسَرَابِيلَثِيَابًا.\ndeeds\nاشكر نعمة الله عليك بالسكن.\nتصدق بصدقة تساعد بها فقيرًا في دفع إيجار مسكنه.\nقل: \"اللهم إني أعوذ بك أن أشرك بك شيئًا أعلمه، وأستغفرك لما لا أعلم\".\nguid\nكن من الذاكرين لنعم الله عليك، المثنين بها عليه.\nمهمة الرسول ليست هداية القلوب، وإنَّما هي بيان الطريق بالبلاغ المبين.\nبعض المخلوقين لا يكتشف ضعف عقله إلا يوم القيامة، بعد فوات الأوان.\nrefl\nوَٱللَّهُ جَعَلَ لَكُم مِّنۢ بُيُوتِكُمۡ سَكَنٗا وَجَعَلَ لَكُم مِّن جُلُودِ ٱلۡأَنۡعَٰمِ بُيُوتٗا تَسۡتَخِفُّونَهَا يَوۡمَ ظَعۡنِكُمۡ وَيَوۡمَ إِقَامَتِكُمۡ وَمِنۡ أَصۡوَافِهَا وَأَوۡبَارِهَا وَأَشۡعَارِهَآ أَثَٰثٗا وَمَتَٰعًا إِلَىٰ حِينٖ ٨٠\nهذا من تعداد النعم التي ألهم الله إليها الإنسان؛ وهي نعمة الفكر بصنع المنازل الواقية والمرفهة، وما يشبهها من الثياب والأثاث عطفًا على جملة (والله أخرجكم من بطون أمهاتكم لا تعلمون شيئًا) [النحل: ٧٨]. وكلها من الألطاف التي أعد الله لها عقل الإنسان وهيأ له وسائلها. ابن عاشور:١٤/٢٣٦.\nما علاقة هذه الآية بقوله تعالى قبلها: (والله أخرجكم من بطون أمهاتكم لا تعلمون شيئًا)؟\nوَجَعَلَ لَكُمۡ سَرَٰبِيلَ تَقِيكُمُ ٱلۡحَرَّ\nلم يذكر الله البرد؛ لأنه قد تقدم أن هذه السورة أولها في أصول النِّعَم وآخرها في مكملاتها ومتمماتها، ووقاية البرد من أصول النعم -فإنه من الضرورة-، وقد ذكره في أولها في قوله: ﴿لَكُمۡ فِيهَا دِفۡءٞ وَمَنَٰفِعُ﴾ [النحل: ٥]. السعدي:٤٤٦.\nلماذا خُصَّ الحَرُّ بالذكر دون البرد في هذه الآية؟\nكَذَٰلِكَ يُتِمُّ نِعۡمَتَهُۥ عَلَيۡكُمۡ\nقال قتادة في قوله تعالى: ﴿كَذَٰلِكَ يُتِمُّ نِعۡمَتَهُۥ عَلَيۡكُمۡ﴾: \"هذه السورة تسمى سورة النِّعَم\". ابن كثير:٢/٥٦١.\nبعض العلماء يسمي سورة النحل: (سورةَ النعم)، فما وجه هذه التسمية؟\nكَذَٰلِكَ يُتِمُّ نِعۡمَتَهُۥ عَلَيۡكُمۡ لَعَلَّكُمۡ تُسۡلِمُونَ ٨١\n(لَعلَّكُم) إذا ذكرتم نعمة الله ورأيتموها غامرة لكم من كل وجه (تُسلِمُونَ) لعظمته، وتنقادون لأمره، وتصرفونها في طاعة موليها ومسديها؛ فكثرة النعم من الأسباب الجالبة من العباد مزيد الشكر، والثناء بها على الله تعالى، ولكن أبى الظالمون إلا تمردًا وعنادًا. السعدي:٤٤٦.\nعندما تَكثُرُ النعم على الشخص، فما الواجب تجاهها؟\nيَعۡرِفُونَ نِعۡمَتَ ٱللَّهِ ثُمَّ يُنكِرُونَهَا وَأَكۡثَرُهُمُ ٱلۡكَٰفِرُونَ ٨٣\n﴿يَعۡرِفُونَ نِعۡمَتَ ٱللَّهِ﴾: إشارة إلى ما ذكر من النعم من أول السورة إلى هنا، والضمير في (يعرفون) للكفار، وإنكارهم لنعم الله إشراكهم به وعبادة غيره. ابن جزي:١/٤٧١.\nكيف يكون الكفار منكرين لنعمة الله مع أنهم يقرون أنه هو الخالق الرازق؟\nثُمَّ لَا يُؤۡذَنُ لِلَّذِينَ كَفَرُواْ وَلَا هُمۡ يُسۡتَعۡتَبُونَ ٨٤\nفلا يؤذن للذين كفروا في الاعتذار؛ لأن اعتذارهم بعد ما عُلم يقينًا بطلان ما هم عليه اعتذارٌ كاذب لا يفيدهم شيئًا. السعدي:٤٤٦.\nلماذا لا يؤذن للذين كفروا في الاعتذار؟\nوَإِذَا رَءَا ٱلَّذِينَ أَشۡرَكُواْ شُرَكَآءَهُمۡ قَالُواْ رَبَّنَا هَٰٓؤُلَآءِ شُرَكَآؤُنَا ٱلَّذِينَ كُنَّا نَدۡعُواْ مِن دُونِكَۖ فَأَلۡقَوۡاْ إِلَيۡهِمُ ٱلۡقَوۡلَ إِنَّكُمۡ لَكَٰذِبُونَ ٨٦\nأي: نطقت بتكذيب مَن عَبدها بأنها لم تكن آلهة، ولا أمرتهم بعبادتها؛ فيُنطق الله الأصنام حتى تظهر عند ذلك فضيحة الكفار.القرطبي:١٢/٤٠٩.\nكيف تكون فضيحة الكفار مع آلهتهم يوم القيامة ؟"],[277,"§النحل\nwords\nالفَحشَاءِمَا قَبُحَ مِنَ الأَكَاذِيبِ.\nوَالبَغيِالظُّلمِ وَالتَّعَدِّي.\nكَفِيلًاضَامِنًا وَشَاهِدًا.\nأَنكَاثًاأَنقَاضًا بَعدَ فَتلِهَا.\nدَخَلًاخَدِيعَةً وَمَكرًا، وَالدَّخَلُ: مَا يَدخُلُ فِي الشَّيءِ لِلفَسَادِ.\nأَربَىأَكثَرَ مَالًا وَمَنفَعَةً.\ndeeds\nاقرأ سورة قرآنية، مستخرجًا منها ثلاث أفكار لإصلاح نفسك.\nأحسن إلى أحد جيرانك بهدية أو كلمة طيبة.\nزر أحد أقاربك.\nguid\nكـن ممن يتذكـرون وينتـفعـون إذا وعظـوا وذكروا بالله تعالى.\nالوفاء بالعهد والصدق بالوعد سبيل أهل الإيمان.\nكن ممن يثبت على العمل الصالح، واحذر من إبطاله، وذهاب أجره.\nrefl\nٱلَّذِينَ كَفَرُواْ وَصَدُّواْ عَن سَبِيلِ ٱللَّهِ زِدۡنَٰهُمۡ عَذَابٗا فَوۡقَ ٱلۡعَذَابِ بِمَا كَانُواْ يُفۡسِدُونَ ٨٨\nأي: عذابًا على كفرهم، وعذابًا على صدهم الناس عن اتباع الحق... وهذا دليل على تفاوت الكفار في عذابهم كما يتفاوت المؤمنون في منازلهم في الجنة ودرجاتهم. ابن كثير:٢/٥٦٢.\nتدل الآية على تفاوت الكفار في دركات جهنم، بيّن ذلك.\nوَيَوۡمَ نَبۡعَثُ فِي كُلِّ أُمَّةٖ شَهِيدًا عَلَيۡهِم مِّنۡ أَنفُسِهِمۡۖ وَجِئۡنَا بِكَ شَهِيدًا عَلَىٰ هَٰٓؤُلَآءِۚ\nهذا من كمال عدل الله تعالى؛ أن كل رسول يشهد على أمته؛ لأنه أعظم اطلاعًا من غيره على أعمال أمته، وأعدل وأشفق من أن يشهد عليهم إلا بما يستحقون. السعدي:٤٤٧.\nفي الآية دليلٌ على كمال عدل الله ورحمته، بَيِّن ذلك.\nوَيَوۡمَ نَبۡعَثُ فِي كُلِّ أُمَّةٖ شَهِيدًا عَلَيۡهِم مِّنۡ أَنفُسِهِمۡۖ وَجِئۡنَا بِكَ شَهِيدًا عَلَىٰ هَٰٓؤُلَآءِۚ\nوزيد في هذه الجملة أن الشهيد يكون من أنفسهم زيادة في التذكير بأن شهادة الرسل على الأمم شهادة لا مطعن لهم فيها؛ لأنها شهود من قومهم؛ لا يجد المشهود عليهم فيها مساغًا للطعن. ابن عاشور:١٤/٢٥٠.\nما فائدة وصف الشهيد في الآية الكريمة بأنه ﴿مِّنۡ أَنفُسِهِمۡ﴾؟\nوَنَزَّلۡنَا عَلَيۡكَ ٱلۡكِتَٰبَ تِبۡيَٰنٗا لِّكُلِّ شَيۡءٖ وَهُدٗى وَرَحۡمَةٗ وَبُشۡرَىٰ لِلۡمُسۡلِمِينَ ٨٩\n﴿لِّكُلِّ شَيۡءٍ﴾ يفيد العموم؛ إلا أنه عموم عرفي في دائرة ما لمثله تجيء الأديان والشّرائع من: إصلاح النفوس، وإكمال الأخلاق، وتقويم المجتمع المدنيّ، وتبيّن الحقوق، وما تتوقّف عليه الدعوة من الاستدلال على الوحدانية، وصدق الرسول. ابن عاشور:١٤/٢٥٣.\nبيّن القرآن الكريم كل ما يحتاجه البشر من عقائد وشرائع وأخلاق، كيف ذلك؟\nإِنَّ ٱللَّهَ يَأۡمُرُ بِٱلۡعَدۡلِ وَٱلۡإِحۡسَٰنِ وَإِيتَآيِٕ ذِي ٱلۡقُرۡبَى\nيدخل في ذلك جميع الأقارب: قريبهم، وبعيدهم، لكن كل ما كان أقرب كان أحق بالبر. السعدي:٤٤٧.\nمن الأقارب المقصودون في الآية؟ ومن أحقهم بالبر؟\nإِنَّ ٱللَّهَ يَأۡمُرُ بِٱلۡعَدۡلِ وَٱلۡإِحۡسَٰنِ وَإِيتَآيِٕ ذِي ٱلۡقُرۡبَىٰ\nوخَصّ الله بالذّكر من جنس أنواع العدل والإحسان نوعًا مُهمًّا يكثر أن يغفل الناس عنه، ويتهاونوا بحقّه أو بفضله؛ وهو: إيتاء ذي القربى؛ فقد تقرّر في نفوس الناس الاعتناء باجتلاب الأبعدِ، واتّقاء شرّه، كما تقرّر في نفوسهم الغفلة عن القريب، والاطمئنان من جانبه، وتعوّد التساهل في حقوقه. ابن عاشور:١٤/٢٥٦.\nلماذا خص إيتاء ذي القربى بالذكر بعد العدل والإحسان مع اندراجه فيها؟\nإِنَّ ٱللَّهَ يَأۡمُرُ بِٱلۡعَدۡلِ وَٱلۡإِحۡسَٰنِ وَإِيتَآيِٕ ذِي ٱلۡقُرۡبَىٰ وَيَنۡهَىٰ عَنِ ٱلۡفَحۡشَآءِ وَٱلۡمُنكَرِ وَٱلۡبَغۡيِۚ يَعِظُكُمۡ لَعَلَّكُمۡ تَذَكَّرُونَ ٩٠\nيعني بالعدل: فعل الواجبات، وبالإحسان: المندوبات؛ وذلك في حقوق الله تعالى وفي حقوق المخلوقين. قال ابن مسعود: \"هذه أجمع آية في كتاب الله تعالى\". ابن جزي:١/٤٧٢.\nلم كانت هذه الآية أجمع آية في كتاب الله؟"],[278,"§النحل\nwords\nيَنفَدُيَذهَبُ وَيَفنَى.\nالرَّجِيمِالمَطرُودِ مِن رَحمَةِ اللهِ.\nسُلطَانٌتَسَلُّطٌ.\nيَتَوَلَّونَهُيَتَّخِذُونَهُ وَلِيًّا مُطَاعًا.\nمُفتَرٍكَاذِبٌ، مُختَلِقٌ عَلَى اللهِ.\nرُوحُ القُدُسِالرُّوحُ المُطَهَّرُ: جِبرِيلُ -عليه السلام-.\ndeeds\nتصدق بصدقة ترجو نفعها وبركتها في الدنيا ويوم القيامة.\nاستعذ بالله من الشيطان الرجيم عند قراءتك للقرآن، خاصة عند قراءة الفاتحة في الصلاة.\nسل الله تعالى أن يجعلك من عباده الذين ليس للشيطان عليهم سلطان.\nguid\nمن فضل الله على الصابر أنه يوم القيامة ينظر إلى أفضل عمل عمله ويجعل من أهله؛ ولو لم يفعله إلا مرة واحدة في عمره.\nالإيمان والتوكل على الله -سبحانه وتعالى- سببان للحماية من شرور إبليس ووساوسه.\nالمداومة على قراءة القرآن من أسباب الثبات على دين الله.\nrefl\nمَا عِندَكُمۡ يَنفَدُ وَمَا عِندَ ٱللَّهِ بَاقٖۗ\nفآثروا ما يبقى على ما يفنى؛ فإن الذي عندكم -ولو كثر جدًا- لا بد أن ينفد ويفنى، وما عند الله باق ببقائه؛ لا يفنى ولا يزول، فليس بعاقل من آثر الفاني الخسيس على الباقي النفيس... وفي هذا الحث والترغيب على الزهد في الدنيا؛ خصوصًا الزهد المتعين، وهو الزهد فيما يكون ضررًا على العبد. السعدي:٤٤٨-٤٤٩.\nما الذي يفيده المسلم العاقل من هذه الآية؟\nمَنۡ عَمِلَ صَٰلِحٗا مِّن ذَكَرٍ أَوۡ أُنثَىٰ وَهُوَ مُؤۡمِنٞ فَلَنُحۡيِيَنَّهُۥ حَيَوٰةٗ طَيِّبَةٗۖ\nفإن الإيمان شرط في صحة الأعمال الصالحة وقبولها، بل لا تسمى أعمالًا صالحة إلا بالإيمان، والإيمان مقتضٍ لها؛ فإنه التصديق الجازم المثمر لأعمال الجوارح من الواجبات والمستحبات. السعدي:٤٤٩.\nلماذا قَيَّد الله الأعمال الصالحة بالإيمان في هذه الآية؟\nمَنۡ عَمِلَ صَٰلِحٗا مِّن ذَكَرٍ أَوۡ أُنثَىٰ وَهُوَ مُؤۡمِنٞ فَلَنُحۡيِيَنَّهُۥ حَيَوٰةٗ طَيِّبَةٗۖ وَلَنَجۡزِيَنَّهُمۡ أَجۡرَهُم بِأَحۡسَنِ مَا كَانُواْ يَعۡمَلُونَ ٩٧\nربط السعادة مع إصلاح العمل. ابن تيمية:٤/١٧٦.\nرُبطت الحياة الطيبة في الآية بأمرين، ما هما؟\nفَإِذَا قَرَأۡتَ ٱلۡقُرۡءَانَ فَٱسۡتَعِذۡ بِٱللَّهِ مِنَ ٱلشَّيۡطَٰنِ ٱلرَّجِيمِ ٩٨\nالمعنى في الاستعاذة عند ابتداء القراءة: لئلَّا يلبس على القارئ قراءته، ويخلط عليه، ويمنعه من التدبر والتفكر. ابن كثير:٢/٥٦٦.\nذُكِرَ في هذه الآية وسيلة ناجعة من وسائل تدبر القرآن الكريم، فما هي؟\nإِنَّهُۥ لَيۡسَ لَهُۥ سُلۡطَٰنٌ عَلَى ٱلَّذِينَ ءَامَنُواْ وَعَلَىٰ رَبِّهِمۡ يَتَوَكَّلُونَ ٩٩\nأي: ليس له عليهم سبيل، ولا يقدر على إضلالهم. ابن جزي:١/٤٧٣.\nما الصفات التي ينبغي الاتصاف بها؛ حتى لا يكون للشيطان عليك سبيل؟\nإِنَّهُۥ لَيۡسَ لَهُۥ سُلۡطَٰنٌ عَلَى ٱلَّذِينَ ءَامَنُواْ وَعَلَىٰ رَبِّهِمۡ يَتَوَكَّلُونَ ٩٩\nقال الثوري: \"ليس له عليهم سلطان أن يوقعهم في ذنب لا يتوبون منه\". ابن كثير:٢/٥٦٦.\nما السلطان المنفي عن إبليس على الذين آمنوا؟\nإِنَّهُۥ لَيۡسَ لَهُۥ سُلۡطَٰنٌ عَلَى ٱلَّذِينَ ءَامَنُواْ وَعَلَىٰ رَبِّهِمۡ يَتَوَكَّلُونَ ٩٩\nفنَفْي سلطان الشيطان مشروط بالأمرين: الإيمان، والتوكّل. ابن عاشور:١٤/٢٧٨.\nما الذي يمنع تسلط الشيطان على الإنسان؟"],[279,"§النحل\nwords\nيُلحِدُونَ إِلَيهِيَنسُبُونَ إِلَيهِ أَنَّهُ عَلَّمَ النَّبِيَّ -صلّى الله عليه وسلّم-.\nطَبَعَخَتَمَ.\nلا جَرَمَحَقًّا.\nفُتِنُواعُذِّبُوا، وَابتُلُوا.\ndeeds\nشارك في بعض المواقع الالكترونية، أو برامج الاتصال للدفاع عن الدين وأهله.\nزر المقبرة، وتذكر أول ليلة لك في القبر.\nاستخرج ثلاث فوائد من الآية.\nguid\nتعلُّم اللـغة العـربية عبـادة؛ لأنـها تـوصل إلى فــهم القرآن الكريم.\nالاستسلام للنفس في تتبع الملذات الدنيوية سببٌ للانحراف.\nمن علامات الغفلة: عدم تتبع المواعظ والذكر ومحاولة الانتفاع بها.\nrefl\nإِنَّمَا يَفۡتَرِي ٱلۡكَذِبَ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِـَٔايَٰتِ ٱللَّهِۖ وَأُوْلَٰٓئِكَ هُمُ ٱلۡكَٰذِبُونَ ١٠٥\nردّ على قولهم: ﴿إِنَّمَآ أَنتَ مُفۡتَرِۭ﴾ [النحل: ١٠١]؛ يعني: إنَّما يليق الكذب بمن لا يؤمن؛ لأنه لا يخاف الله، وأمَّا من يؤمن بالله فلا يكذب عليه. ابن جزي:١/٤٧٤.\nالإيمان ينافي الكذب، وضح ذلك من الآية.\nمَن كَفَرَ بِٱللَّهِ مِنۢ بَعۡدِ إِيمَٰنِهِۦٓ إِلَّا مَنۡ أُكۡرِهَ وَقَلۡبُهُۥ مُطۡمَئِنُّۢ بِٱلۡإِيمَٰنِ\nمن أُكره على الكفر، وأُجبر عليه وقلبه مطمئن بالإيمان راغب فيه؛ فإنه لا حرج عليه، ولا إثم. السعدي:٤٥٠.\nإذا توفرت شروط الإكراه، فإن رحمة الله أوسع من تضييق العباد، وضح ذلك من الآية.\nوَلَٰكِن مَّن شَرَحَ بِٱلۡكُفۡرِ صَدۡرٗا فَعَلَيۡهِمۡ غَضَبٞ مِّنَ ٱللَّهِ وَلَهُمۡ عَذَابٌ عَظِيمٞ ١٠٦\nأخبر تعالى عمن كفر به بعد الإيمان والتبصر، وشرح صدره بالكفر واطمأن به؛ أنه قد غضب عليه؛ لعلمهم بالإيمان، ثم عدولهم عنه. ابن كثير:٢/٥٦٨.\nلماذا كان ذنب المرتد عن الإسلام أعظم من ذنب الكافر الأصلي؟\nمَن كَفَرَ بِٱللَّهِ مِنۢ بَعۡدِ إِيمَٰنِهِۦٓ إِلَّا مَنۡ أُكۡرِهَ وَقَلۡبُهُۥ مُطۡمَئِنُّۢ بِٱلۡإِيمَٰنِ وَلَٰكِن مَّن شَرَحَ بِٱلۡكُفۡرِ صَدۡرٗا فَعَلَيۡهِمۡ غَضَبٞ مِّنَ ٱللَّهِ وَلَهُمۡ عَذَابٌ عَظِيمٞ ١٠٦\nأجمع العلماء على أن من أكره على الكفر فاختار القتل؛ أنه أعظم أجرًا عند الله ممن اختار الرخصة. القرطبي:١٢/٤٤٤.\nبيّن المراتب الجائزة للمكرَه حسب الأفضلية.\nذَٰلِكَ بِأَنَّهُمُ ٱسۡتَحَبُّواْ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا عَلَى ٱلۡأٓخِرَةِ وَأَنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡكَٰفِرِينَ ١٠٧\nفأقدموا على ما أقدموا عليه من الردة لأجل الدنيا. ابن كثير:٢/٥٦٨.\nبينت الآية سببًا كبيرًا لردّةِ كثير من المرتدين، فما هو؟\nذَٰلِكَ بِأَنَّهُمُ ٱسۡتَحَبُّواْ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا عَلَى ٱلۡأٓخِرَةِ وَأَنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡكَٰفِرِينَ ١٠٧\nالله -سبحانه وتعالى- جعل استحباب الدنيا على الآخرة هو الأصل الموجب للخسران. ابن تيمية:٤/١٨٥.\nما الأصل الذي تعود إليه ضلالات الكفار؟\nأُوْلَٰٓئِكَ ٱلَّذِينَ طَبَعَ ٱللَّهُ عَلَىٰ قُلُوبِهِمۡ وَسَمۡعِهِمۡ وَأَبۡصَٰرِهِمۡۖ وَأُوْلَٰٓئِكَ هُمُ ٱلۡغَٰفِلُونَ ١٠٨\nثم وصفهم فقال: ﴿أُوْلَٰٓئِكَ ٱلَّذِينَ طَبَعَ ٱللَّهُ عَلَىٰ قُلُوبِهِمۡ﴾ أَي: عن فهم المواعظ، (وسمعهم) عن كلام اللَّهِ تعالى، (وأبصارهم) عن النَّظر في الآيَات، ﴿وَأُوْلَٰٓئِكَ هُمُ ٱلۡغَٰفِلُونَ﴾ عَمَّا يُرَادُ بهم. القرطبي:١٢/٤٤٩.\nما أثر الطبع على القلوب والأبصار والأسماع؟"],[280,"§النحل\nwords\nرَغَدًاهَنِيئًا سَهلًا.\nغَيرَ بَاغٍغَيرَ مُرِيدٍ وَلا طَالِبٍ لِلمُحَرَّمِ.\nوَلا عَادٍوغَيرَ مُتَجَاوِزٍ حَدَّ الضَّرُورَةِ مِمَّا يَسُدُّ الرَّمَقَ.\ndeeds\nاشتغل اليوم بعيوبك؛ بالتفكر فيها، ومعرفة طرق إصلاحها.\nأرسل رسالة تحذر فيها من أمثلة موجودة في المجتمع للكفر بالنعمة.\nسم الله تعالى قبل الأكل، واحمده بعده، وإذا بقي منك طعام صالح للأكل فاذهب به إلى أحد المحتاجين.\nguid\nتأمل في أسباب إهلاك الله تعالى للأمم والدول قديمًا وحديثًا.\nاحذر من أكل ما لم يذكر اسم الله عليه، وكذب المصانع في ذلك؛ فإنه سبب لرد دعائك وبعدك عن ربك.\nإذا جاءك الداعية أو الناصح فاقبل منه الحق، منقادًا لأوامر الله.\nrefl\nيَوْمَ تَأْتِى كُلُّ نَفْسٍۢ تُجَٰدِلُ عَن نَّفْسِهَا وَتُوَفَّىٰ كُلُّ نَفْسٍۢ مَّا عَمِلَتْ وَهُمْ لَا يُظْلَمُونَ ١١١\n﴿۞يَوۡمَ تَأۡتِي كُلُّ نَفۡسٍ تُجَٰدِلُ عَن نَّفۡسِهَا﴾: تخاصم، وتحتج عَن نَفسِها بما أسلفت من خير وشر، مشتغلًا بها، لا تتفرغ إلى غيرها. البغوي:٢/٦٤١.\nمتى ينشغل العبد بنفسه ولا يتفرغ لعيوب الآخرين؟\nوَضَرَبَ ٱللَّهُ مَثَلًا قَرْيَةً كَانَتْ ءَامِنَةً مُّطْمَئِنَّةً يَأْتِيهَا رِزْقُهَا رَغَدًا مِّن كُلِّ مَكَانٍۢ فَكَفَرَتْ بِأَنْعُمِ ٱللَّهِ فَأَذَٰقَهَا ٱللَّهُ لِبَاسَ ٱلْجُوعِ وَٱلْخَوْفِ بِمَا كَانُواْ يَصْنَعُونَ ١١٢\nوقدم الأمن على الطمأنينة؛ إذ لا تحصل الطمأنينة بدونه، كما أن الخوف يسبّب الانزعاج والقلق. ابن عاشور:١٤/٣٠٥.\nلماذا قدم الأمن على الطمأنينة في الآية الكريمة؟\nوَضَرَبَ ٱللَّهُ مَثَلًا قَرْيَةً كَانَتْ ءَامِنَةً مُّطْمَئِنَّةً يَأْتِيهَا رِزْقُهَا رَغَدًا مِّن كُلِّ مَكَانٍۢ فَكَفَرَتْ بِأَنْعُمِ ٱللَّهِ فَأَذَٰقَهَا ٱللَّهُ لِبَاسَ ٱلْجُوعِ وَٱلْخَوْفِ بِمَا كَانُواْ يَصْنَعُونَ ١١٢\nسماه لباسًا؛ لأنه يظهر عليهم، من الهزال وشحوبة اللون وسوء الحال، ما هو كاللباس. القرطبي:١٢/٤٥٢.\nلمَ سمى الله تعالى الجوع والخوف النازل بالأمم الهالكة لباسًا؟\nوَضَرَبَ ٱللَّهُ مَثَلًا قَرْيَةً كَانَتْ ءَامِنَةً مُّطْمَئِنَّةً يَأْتِيهَا رِزْقُهَا رَغَدًا مِّن كُلِّ مَكَانٍۢ فَكَفَرَتْ بِأَنْعُمِ ٱللَّهِ فَأَذَٰقَهَا ٱللَّهُ لِبَاسَ ٱلْجُوعِ وَٱلْخَوْفِ بِمَا كَانُواْ يَصْنَعُونَ ١١٢\nجعلهم مثَلًا وعظة لمن يأتي بمثل ما أتوا به من إنكار نعمة الله. ابن عاشور:١٤/٣٠٣.\nكيف تكون القرى المهلكة مثلًا وعِظةً لغيرها؟\nإِنَّمَا حَرَّمَ عَلَيۡكُمُ ٱلۡمَيۡتَةَ وَٱلدَّمَ وَلَحۡمَ ٱلۡخِنزِيرِ وَمَآ أُهِلَّ لِغَيۡرِ ٱللَّهِ بِهِۦۖ\nفالله تعالى ما حرَّم علينا إلا الخبيثات؛ تفضلًا منه، وصيانة عن كل مستقذر. السعدي:٤٥١.\nما علّة التحريم في الأطعمة المحرمة؟\nوَلَا تَقُولُواْ لِمَا تَصِفُ أَلۡسِنَتُكُمُ ٱلۡكَذِبَ هَٰذَا حَلَٰلٞ وَهَٰذَا حَرَامٞ لِّتَفۡتَرُواْ عَلَى ٱللَّهِ ٱلۡكَذِبَۚ إِنَّ ٱلَّذِينَ يَفۡتَرُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَ لَا يُفۡلِحُونَ ١١٦\nويدخل في هذا كل من ابتدع بدعة ليس له فيها مستند شرعي. ابن كثير:٢/٥٧٠.\nكيف تدل الآية على تحريم البِدَعِ في الدين؟\nوَلَا تَقُولُواْ لِمَا تَصِفُ أَلۡسِنَتُكُمُ ٱلۡكَذِبَ هَٰذَا حَلَٰلٞ وَهَٰذَا حَرَامٞ لِّتَفۡتَرُواْ عَلَى ٱللَّهِ ٱلۡكَذِبَۚ إِنَّ ٱلَّذِينَ يَفۡتَرُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَ لَا يُفۡلِحُونَ ١١٦\nهذه الآية مخاطبة للعرب الذين أحلوا أشياء، وحرموا أشياء؛ كالبحيرة وغيرها مما ذكر في سورة المائدة والأنعام، ثم يدخل فيها كل من قال: هذا حلال وهذا حرام بغير علم. ابن جزي:١/٤٧٦.\nبيّن الأصناف الذين يدخلون في هذه الآية."],[281,"§النحل\nwords\nبِجَهَالَةٍبِسَفَهٍ، وَجَهلٍ لِعَاقِبَتِهَا، وَكُلُّ مَن عَصَى اللهَ فَهُوَ جَاهِلٌ.\nأُمَّةًإِمَامًا، جَامِعًا لِخِصَالِ الخَيرِ.\nقَانِتًاخَاضِعًا، مُدَاوِمًا عَلَى الطَّاعَةِ.\nحَنِيفًامَائِلًا عَنِ الشِّركِ إِلَى التَّوحِيدِ قَصدًا.\nاجتَبَاهُاختَارَهُ.\nسَبِيلِ رَبِّكَدِينِ رَبِّكَ، وَطَرِيقِهِ المُستَقِيمِ.\ndeeds\nاستخرج الأساليب الدعوية في هذه الآية وطبقها في عمل دعوي هذا اليوم.\nتدرب مع صديقك اليوم على الجدال بالتي هي أحسن.\nتذكر ذنبًا ارتكبته وأنت جاهل، ثم استغفر الله منه.\nguid\nمن أساليب الدعوة استخدام الحكمة والموعظة الحسنة والمجادلة بالتي هي أحسن.\nإذا أراد الله بعبد خيرًا رزقه الصبر.\nالتقوى والإحسان سببان لحصول معية الله للعبد.\nrefl\nثُمَّ إِنَّ رَبَّكَ لِلَّذِينَ عَمِلُواْ ٱلسُّوٓءَ بِجَهَٰلَةٖ ثُمَّ تَابُواْ مِنۢ بَعۡدِ ذَٰلِكَ وَأَصۡلَحُوٓاْ إِنَّ رَبَّكَ مِنۢ بَعۡدِهَا لَغَفُورٞ رَّحِيمٌ ١١٩\nأخبر تعالى تكرمًا وامتنانًا في حق العصاة المؤمنين أن من تاب منهم إليه تاب عليه، فقال: ﴿ثُمَّ إِنَّ رَبَّكَ لِلَّذِينَ عَمِلُواْ ٱلسُّوٓءَ بِجَهَٰلَةٍ﴾ قال بعض السلف: \"كل من عصى الله فهو جاهل\". ابن كثير:٢/٥٧١.\nلماذا يوصف العاصي بالجهل؟\nثُمَّ إِنَّ رَبَّكَ لِلَّذِينَ عَمِلُواْ ٱلسُّوٓءَ بِجَهَٰلَةٖ ثُمَّ تَابُواْ مِنۢ بَعۡدِ ذَٰلِكَ وَأَصۡلَحُوٓاْ إِنَّ رَبَّكَ مِنۢ بَعۡدِهَا لَغَفُورٞ رَّحِيمٌ ١١٩\nمعنى الإصلاح: الاستقامة على التوبة. البغوي:٢/٦٤٣.\nما المقصود بقوله تعالى ﴿ثُمَّ تَابُواْ مِنۢ بَعۡدِ ذَٰلِكَ وَأَصۡلَحُوٓاْ﴾؟\nإِنَّ إِبۡرَٰهِيمَ كَانَ أُمَّةٗ قَانِتٗا لِّلَّهِ حَنِيفٗا وَلَمۡ يَكُ مِنَ ٱلۡمُشۡرِكِينَ ١٢٠\n﴿إِنَّ إِبۡرَٰهِيمَ كَانَ أُمَّةً﴾: فيه وجهان؛ أحدهما: أنه كان وحده أمة من الأمم بكماله، وجمعه لصفات الخير... والآخر: أن يكون أمة بمعنى إمامًا؛ كقوله: ﴿إِنِّي جَاعِلُكَ لِلنَّاسِ إِمَامٗا﴾ [البقرة: ١٢٤]، قال ابن مسعود: \"والأمة: معلم الناس الخير\". ابن جزي:١/٤٧٧.\nتضمنت كلمة (أمة) عدة صفات اتصف بها إبراهيم -عليه السلام-، فما هي؟\nوَلَمۡ يَكُ مِنَ ٱلۡمُشۡرِكِينَ ١٢٠\nنفى عنه الشرك لقصد الرد على المشركين من العرب الذين كانوا ينتمون إليه. ابن جزي:١/٤٧٧.\nمن انتسب للنبي أو آل بيته وهو مشرك؛ فهل ينفعه ذلك شيئًا؟\nٱدۡعُ إِلَىٰ سَبِيلِ رَبِّكَ بِٱلۡحِكۡمَةِ وَٱلۡمَوۡعِظَةِ ٱلۡحَسَنَةِۖ وَجَٰدِلۡهُم بِٱلَّتِي هِيَ أَحۡسَنُۚ إِنَّ رَبَّكَ هُوَ أَعۡلَمُ بِمَن ضَلَّ عَن سَبِيلِهِۦ وَهُوَ أَعۡلَمُ بِٱلۡمُهۡتَدِينَ ١٢٥\nالمراد بالسبيل هنا: الإسلام، و(الحكمة) هي الكلام الذي يظهر صوابه، و(الموعظة) هي الترغيب والترهيب، والجدال هو الردّ على المخالف. وهذه الأشياء الثلاثة يسميها أهل العلوم العقلية: بالبرهان، والخطابة، والجدال. ابن جزي:١/٤٧٨.\nتحدث عن مقومات الدعوة الناجحة من خلال هذه الآية.\nوَجَٰدِلۡهُم بِٱلَّتِي هِيَ أَحۡسَنُۚ\nفيجادل بالتي هي أحسن، وهي الطرق التي تكون أدعى لاستجابته عقلًا ونقلًا، ومن ذلك: الاحتجاج عليه بالأدلة التي كان يعتقدها؛ فإنه أقرب إلى حصول المقصود، وأن لا تؤدي المجادلة إلى خصام أو مشاتمة تذهب بمقصودها ولا تحصل الفائدة منها، بل يكون القصد منها هداية الخلق إلى الحق، لا المغالبة ونحوها. السعدي:٤٥٢.\nكيف تكون المجادلة بالتي هي أحسن؟\nوَٱصۡبِرۡ وَمَا صَبۡرُكَ إِلَّا بِٱللَّهِۚ\nأي: بمعونة الله وتوفيقه. البغوي:٢/٦٤٧.\nهل يستطيع العبد أن يحقق الصبر بنفسه؟"],[282,"§الإسراء\nwords\nوَكِيلًامَعبُودًا تُفَوِّضُونَ أُمُورَكُم إِلَيهِ.\nفَجَاسُوافَطَافُوا.\nالكَرَّةَالغَلَبَةَ وَالظُّهُورَ.\nوَلِيُتَبِّرُوالِيُدَمِّرُوا.\nتَتبِيرًاتَدمِيرًا كَامِلًا.\ndeeds\nقل: \"سبحان الله\"، وكرر ذكرها؛ فهي تعظيم لله تعالى، وهي من أحب الكلام إلى الله تعالى، وهي تنزيه يختص بالله تعالى وحده.\nاجتمع مع بعض إخوانك، أو زملائك، ثم أقرأوا حادثة الإسراء والمعراج من صحيح البخاري، أو من تفسير ابن كثير.\nتذكر خمسًا من أكبر نعم الله عليك، واشكر الله عليها؛ اقتداء بالأنبياء في شكرهم لله تعالى.\nguid\nاتخِذِ الله -سبحانه وتعالى- وكيلًا لك في جميع أمورك.\nما قضاه الله تعالى كائن، وما وعد به ناجِز، والإيمان بذلك واجب.\nالشكر من صفات الرسل؛ فبهداهم اقتده.\nrefl\nسُبۡحَٰنَ ٱلَّذِيٓ أَسۡرَىٰ بِعَبۡدِهِۦ لَيۡلٗا مِّنَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ إِلَى ٱلۡمَسۡجِدِ ٱلۡأَقۡصَا ٱلَّذِي بَٰرَكۡنَا حَوۡلَهُۥ لِنُرِيَهُۥ مِنۡ ءَايَٰتِنَآۚ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلۡبَصِيرُ ١\nالافتتاح بكلمة التسبيح من دون سبق كلام مُتضمّنٍ ما يَجب تنزيه الله عنه يؤذن بأن خبرًا عجيبًا يستقبله السامعون؛ دالًا على عظيم القدرة من المتكلم، ورفيع منزلة المتحدث عنه. ابن عاشور:١٥/٩.\nبيّن فائدة الافتتاح بالتسبيح في الآية الكريمة.\nسُبۡحَٰنَ ٱلَّذِيٓ أَسۡرَىٰ بِعَبۡدِهِۦ لَيۡلٗا مِّنَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ إِلَى ٱلۡمَسۡجِدِ ٱلۡأَقۡصَا\nوالحق أنه -عليه السلام- أُسري به يقظةً لا منامًا... فالتسبيح إنَّما يكون عند الأمور العظام، فلو كان منامًا لم يكن فيه كبير شيء، ولم يكن مستعظمًا، ولما بادرت كفار قريش إلى تكذيبه، ولما ارتدت جماعة ممن كان قد أسلم. وأيضًا فإن العبد عبارة عن مجموع الروح والجسد، وقد قال: ﴿أَسۡرَىٰ بِعَبۡدِهِۦ﴾. ابن كثير:٣/٢٣.\nهل أُسري بروح النبي فقط، أم بروحه وجسده؟ وضح ذلك.\nسُبۡحَٰنَ ٱلَّذِيٓ أَسۡرَىٰ بِعَبۡدِهِۦ\nوذكره هنا بصفة العبودية؛ لأنه نال هذه المقامات الكبار بتكميله لعبودية ربه. السعدي:٤٥٣.\nما الحكمة من وصف النبي بالعبودية في هذا المقام؟\nوَءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ وَجَعَلۡنَٰهُ هُدٗى لِّبَنِيٓ إِسۡرَٰٓءِيلَ أَلَّا تَتَّخِذُواْ مِن دُونِي وَكِيلٗا ٢\nنهى أن يتخذ من دونه وكيلًا؛ لأن المخلوق لا يستقل بجميع حاجات العبد. والوكالة الجائزة أن يوكل الإنسان في فعل يقدر عليه، فيحصل للموكل بذلك بعض مطلوبه، فأما مطالبه كلها فلا يقدر عليها إلا الله. ابن تيمية:٤/٢٠٢.\nلماذا نهينا عن اتخاذ وكيل من دون الله؟\nذُرِّيَّةَ مَنۡ حَمَلۡنَا مَعَ نُوحٍۚ إِنَّهُۥ كَانَ عَبۡدٗا شَكُورٗا ٣\nأي: كثير الشكر؛ كان يحمد الله على كل حال، وهذا تعليل لما تقدم؛ أي: كونوا شاكرين كما كان أبوكم نوح. ابن جزي:١/٤٨١.\nلم خص الله نوحًا -عليه السلام- بصفة الشكر مع اتصافه بغيرها من الصفات؟\nفَإِذَا جَآءَ وَعۡدُ أُولَىٰهُمَا بَعَثۡنَا عَلَيۡكُمۡ عِبَادٗا لَّنَآ أُوْلِي بَأۡسٖ شَدِيدٖ فَجَاسُواْ خِلَٰلَ ٱلدِّيَارِۚ وَكَانَ وَعۡدٗا مَّفۡعُولٗا ٥ ثُمَّ رَدَدۡنَا لَكُمُ ٱلۡكَرَّةَ عَلَيۡهِمۡ وَأَمۡدَدۡنَٰكُم بِأَمۡوَٰلٖ وَبَنِينَ وَجَعَلۡنَٰكُمۡ أَكۡثَرَ نَفِيرًا ٦\nفكان ظهور بني إسرائيل على عدوهم تارة، وظهور عدوهم تارة من دلائل نبوة موسى -عليه السلام-، وكذلك ظهور أمة محمد-صلى الله عليه وسلم- على عدوهم تارة، وظهور عدوهم عليهم تارة هو من دلائل رسالة محمد -صلى الله عليه وسلم-وأعلام نبوته. ابن تيمية:٤/٢٠٣.\nبينت الآيات ظهور بني إسرائيل على عدوهم تارة، وظهور عدوهم عليهم تارة أخرى، فعلى ماذا يدل ذلك؟\nإِنۡ أَحۡسَنتُمۡ أَحۡسَنتُمۡ لِأَنفُسِكُمۡۖ وَإِنۡ أَسَأۡتُمۡ فَلَهَاۚ\nمعنى ﴿إِنۡ أَحۡسَنتُمۡ أَحۡسَنتُمۡ لِأَنفُسِكُمۡۖ﴾ أننا نرد لكم الكرة لأجل التوبة وتجدد الجيل وقد أصبحتم في حالة نعمة؛ فإن أحسنتم كان جزاؤكم حسنًا، وإن أسأتم أسأتم لأنفسكم؛ فكما أهلكنا من قبلكم بذنوبهم فقد أحسنا إليكم بتوبتكم، فاحذروا الإساءة كيلا تصيروا إلى مصير من قبلكم. ابن عاشور:١٥/٢٨.\nفي الآية بشارة ونذارة، فمما كانت النذارة؟"],[283,"§الإسراء\nwords\nحَصِيرًاسِجنًا لا خُرُوجَ مِنهُ أَبَدًا.\nأَقوَمُأَعدَلُ، وَأَصوَبُ.\nفَمَحَونَاطَمَسنَا.\nمُبصِرَةًمُضِيئَةً.\nطَائِرَهُمَا عَمِلَهُ مِن خَيرٍ وَشَرٍّ.\nوَلا تَزِرُلا تَحمِلُ.\nوَازِرَةٌنَفسٌ آثِمَةٌ.\ndeeds\nحدد أمرًا أهمك، ثم ابحث عن آيات تتحدث عنه وامتثل تعاليمها حتى ييسره الله لك.\nادع لنفسك وأهلك بالصلاح والخير.\nأرسل رسالة تبيّن فيها خطر الترف وآثاره السيئة.\nguid\nاحذر عند الغضب من أن تدعو على نفسك أو أولادك أو مالك بالشر، واحذر العجلة في الأمور، وكن متريثًا صبورًا.\nلا تخالف الفطرة السوية التي خلقنا الله عليها؛ وتجعل ليلك عملًا ونهارك نومًا.\nفسق الآخرين وفجورهم قد يكون سببًا لهلاكك ومن حولك إذا لم تأمروا بالمعروف وتنهوا عن المنكر.\nrefl\nعَسَىٰ رَبُّكُمۡ أَن يَرۡحَمَكُمۡۚ وَإِنۡ عُدتُّمۡ عُدۡنَاۚ وَجَعَلۡنَا جَهَنَّمَ لِلۡكَٰفِرِينَ حَصِيرًا ٨\nفي هذه الآيات التحذير لهذه الأمة من العمل بالمعاصي لئلَّا يصيبهم ما أصاب بني إسرائيل؛ فسنة الله واحدة؛ لا تُبَدَّلُ ولا تُغَيَّرُ، ومن نظر إلى تسليط الكفرة على المسلمين والظلمة عرف أن ذلك من أجل ذنوبهم؛ عقوبة لهم، وأنهم إذا أقاموا كتاب الله وسنة رسوله مكن لهم في الأرض، ونصرهم على أعدائهم. السعدي:٤٥٤.\nعندما تقرأ آية من القرآن تتحدث عن أمة أخرى، فكيف تستفيد من مثل هذه الآيات في دعوتك؟\nإِنَّ هَٰذَا ٱلۡقُرۡءَانَ يَهۡدِي لِلَّتِي هِيَ أَقۡوَمُ وَيُبَشِّرُ ٱلۡمُؤۡمِنِينَ ٱلَّذِينَ يَعۡمَلُونَ ٱلصَّٰلِحَٰتِ أَنَّ لَهُمۡ أَجۡرٗا كَبِيرٗا ٩\nوالمعنى: أنه يهدي للتي هي أقوم من هُدى كتاب بني إسرائيل الذي في قوله: (وجعلناه هدى لبني إسرائيل)؛ ففيه إيماء إلى ضمان سلامة أمة القرآن من الحيدة عن الطريق الأقوم. ابن عاشور:١٥/٤٠.\nالقرآن الكريم عصمة من الهلكة، بيّن كيف دلت الآية الكريمة على ذلك؟\nوَيَدۡعُ ٱلۡإِنسَٰنُ بِٱلشَّرِّ دُعَآءَهُۥ بِٱلۡخَيۡرِۖ وَكَانَ ٱلۡإِنسَٰنُ عَجُولٗا ١١\nقال ابن عباس -رضي الله عنهما- وغيره: \"هو دعاء الرجل على نفسه وولده -عند الضجر- بما لا يحب أن يستجاب له\". القرطبي:١٣/٣٤.\nبيّن صورة من صور عجلة الإنسان.\nوَيَدۡعُ ٱلۡإِنسَٰنُ بِٱلشَّرِّ دُعَآءَهُۥ بِٱلۡخَيۡرِۖ وَكَانَ ٱلۡإِنسَٰنُ عَجُولٗا ١١\nذمٌ وعتاب لما يفعله الناس عند الغضب من الدعاء على أنفسهم وأموالهم وأولادهم، وأنهم يدعون بالشر في ذلك الوقت، كما يدعون بالخير في وقت التثبت. ابن جزي:١/٤٨٣.\nقد يجلب بعض الناس الشر لأنفسهم، وضح ذلك من خلال الآية.\nوَجَعَلۡنَا ٱلَّيۡلَ وَٱلنَّهَارَ ءَايَتَيۡنِۖ فَمَحَوۡنَآ ءَايَةَ ٱلَّيۡلِ وَجَعَلۡنَآ ءَايَةَ ٱلنَّهَارِ مُبۡصِرَةٗ لِّتَبۡتَغُواْ فَضۡلٗا مِّن رَّبِّكُمۡ وَلِتَعۡلَمُواْ عَدَدَ ٱلسِّنِينَ وَٱلۡحِسَابَۚ وَكُلَّ شَيۡءٖ فَصَّلۡنَٰهُ تَفۡصِيلٗا ١٢\nأي: علامتين على وحدانيتنا، ووجودنا، وكمال علمنا وقدرتنا، والآية فيهما: إقبال كل منهما من حيث لا يعلم، وإدباره إلى حيث لا يعلم، ونقصان أحدهما بزيادة الآخر، وبالعكس آية أيضًا، وكذلك ضوء النهار وظلمة الليل. القرطبي:١٣/٣٧.\nما وجه كون الليل والنهار آيتين؟\nٱقۡرَأۡ كِتَٰبَكَ كَفَىٰ بِنَفۡسِكَ ٱلۡيَوۡمَ عَلَيۡكَ حَسِيبٗا ١٤\nوهذا من أعظم العدل والإنصاف؛ أن يقال للعبد: حاسب نفسك؛ ليعترف بما عليه من الحق الموجب للعقاب. السعدي:٤٥٥.\nمن خلال هذه الآية تحدث عن كمال عدل الله -سبحانه وتعالى-.\nوَكَمۡ أَهۡلَكۡنَا مِنَ ٱلۡقُرُونِ مِنۢ بَعۡدِ نُوحٖۗ\nومعناه: أنكم أيها المكذبون لستم أكرم على الله منهم، وقد كذبتم أشرف الرسل وأكرم الخلائق؛ فعقوبتكم أولى وأحرى. ابن كثير:٣/٣٣.\nما المراد من الإخبار بأن الله قد أهلك أممًا كثيرة بعد قوم نوح؟"]])